const HTML = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>Endurance Brain — Institutional memory, finally autonomous.</title>\n<meta name=\"description\" content=\"Endurance Brain turns everything your firm produces — email, chat, documents, meetings, deals, code, your TMS, your CRM — into a living, self-maintaining knowledge base that answers with citations and never hallucinates. Proven in production. By Endurance AI Labs.\" />\n<style>\n  :root{\n    /* Margins light foundation */\n    --bg:#f7f8fa; --bg2:#eef1f5; --surface:#ffffff;\n    --ink:#1b2230; --muted:#5b6472; --muted2:#97a0ad;\n    --line:#e6e8ec; --line2:#d4d8df;\n    --blue:#2766d6; --blue-press:#1f54b8; --blue-soft:#eaf2fd; --blue-tint:#cfe0f8;\n    --deep:#1b3e63; --deep2:#245489;\n    /* Terminal dark layer */\n    --tl-ink:#0a1120; --tl-ink2:#0d1526; --tl-panel:#101a30;\n    --tl-line:rgba(148,176,230,.14); --tl-line2:rgba(148,176,230,.24);\n    --tl-bone:#f4f6fa; --tl-muted:#93a3c0; --tl-accent:#4a86f7; --tl-accent2:#7fa9ff; --tl-amber:#c7a76c;\n    /* Status — muted, earthy */\n    --good:#4f7d5d; --good-bg:#eaf2ec; --warn:#b98a36; --warn-bg:#f6efde; --bad:#b1503f; --bad-bg:#f7e9e5;\n    --sans:ui-sans-serif,system-ui,-apple-system,\"Segoe UI\",Roboto,Helvetica,Arial,sans-serif;\n    --mono:ui-monospace,\"SF Mono\",\"Cascadia Code\",\"Roboto Mono\",Menlo,Consolas,monospace;\n    --maxw:1180px; --r:12px; --r-sm:8px;\n    --shadow:0 1px 2px rgba(30,30,36,.04), 0 4px 16px rgba(30,30,36,.05);\n    --shadow-lift:0 2px 4px rgba(30,30,36,.05), 0 14px 40px rgba(30,30,36,.09);\n  }\n  *{box-sizing:border-box;margin:0;padding:0}\n  html{scroll-behavior:auto}\n  body{\n    background:var(--bg); color:var(--ink); font-family:var(--sans);\n    font-weight:400; line-height:1.6; -webkit-font-smoothing:antialiased; overflow-x:hidden;\n  }\n  a{color:inherit;text-decoration:none}\n  .wrap{max-width:var(--maxw);margin:0 auto;padding:0 28px}\n  .eyebrow{font-size:10.5px;font-weight:700;letter-spacing:.24em;text-transform:uppercase;color:var(--blue);font-family:var(--mono)}\n  .eyebrow .dot{color:var(--tl-amber)}\n  h1,h2{font-weight:800;letter-spacing:-.025em;line-height:1.05}\n  h3{letter-spacing:-.01em;line-height:1.15;font-weight:700}\n  .blue{color:var(--blue)}\n  .mono{font-family:var(--mono)}\n\n  /* ---------- NAV ---------- */\n  header.nav{\n    position:fixed;top:0;left:0;right:0;z-index:100;\n    backdrop-filter:blur(14px);\n    background:rgba(10,17,32,.55);\n    border-bottom:1px solid transparent;\n    transition:background .35s,border-color .35s;\n  }\n  header.nav .nav-in{display:flex;align-items:center;justify-content:space-between;height:64px;max-width:1320px;margin:0 auto;padding:0 28px}\n  .brand{display:flex;align-items:center;gap:13px;font-weight:800;letter-spacing:-.01em;font-size:16px}\n  .brand .wordmark{height:19px;width:auto;display:block}\n  .brand .wm-dark{display:none}\n  .brand .bdiv{width:1px;height:18px;background:var(--tl-line2);display:block;transition:background .35s}\n  .brand .bprod{color:var(--tl-accent);font-weight:800;font-size:16.5px;letter-spacing:-.01em;transition:color .35s}\n  .nav-links{display:flex;gap:20px;align-items:center}\n  .nav-links a{font-size:13px;color:var(--tl-muted);transition:color .2s;font-weight:600;white-space:nowrap}\n  .nav-links a:hover,.nav-links a.active{color:var(--tl-bone)}\n  .nav-links a.nav-reel{color:var(--tl-accent)}\n  .nav-links a.nav-reel:hover{color:var(--tl-accent2)}\n  .btn{display:inline-flex;align-items:center;gap:8px;font-size:14px;font-weight:700;padding:10px 18px;border-radius:9px;transition:.2s;cursor:pointer;border:1px solid transparent;white-space:nowrap;font-family:var(--sans)}\n  .btn-blue{background:var(--blue);color:#fff}\n  .btn-blue:hover{background:var(--blue-press);box-shadow:0 8px 26px rgba(39,102,214,.30);transform:translateY(-1px)}\n  .btn-ghost{border-color:var(--tl-line2);color:var(--tl-bone)}\n  .btn-ghost:hover{border-color:var(--tl-accent);color:var(--tl-accent2)}\n  .nav-cta{display:flex;gap:10px;align-items:center}\n  /* nav flips to paper once past the hero */\n  header.nav.paper{background:rgba(255,255,255,.88);border-bottom:1px solid var(--line)}\n  header.nav.paper .nav-links a{color:var(--muted)}\n  header.nav.paper .nav-links a:hover,header.nav.paper .nav-links a.active{color:var(--ink)}\n  header.nav.paper .nav-links a.active{color:var(--blue)}\n  header.nav.paper .nav-links a.nav-reel{color:var(--blue)}\n  header.nav.paper .brand .bprod{color:var(--blue)}\n  header.nav.paper .brand .bdiv{background:var(--line2)}\n  header.nav.paper .btn-ghost{border-color:var(--line2);color:var(--ink)}\n  header.nav.paper .btn-ghost:hover{border-color:var(--blue);color:var(--blue)}\n  header.nav.paper .wm-light{display:none}\n  header.nav.paper .wm-dark{display:block}\n\n  /* progress bar */\n  .progress{position:fixed;top:0;left:0;height:2px;background:linear-gradient(90deg,var(--blue),var(--tl-accent2));width:0;z-index:101;transition:none}\n\n  /* ---------- DOT RAIL ---------- */\n  .rail{position:fixed;right:18px;top:50%;transform:translateY(-50%);z-index:90;display:flex;flex-direction:column;gap:12px}\n  .rail a{position:relative;width:9px;height:9px;border-radius:50%;background:var(--line2);transition:.25s;display:block}\n  .rail a:hover{background:var(--muted2)}\n  .rail a.on{background:var(--blue);box-shadow:0 0 0 4px var(--blue-soft)}\n  .rail.dark a{background:rgba(148,176,230,.28)}\n  .rail.dark a:hover{background:var(--tl-muted)}\n  .rail.dark a.on{background:var(--tl-accent);box-shadow:0 0 0 4px rgba(74,134,247,.18)}\n  .rail a span{\n    position:absolute;right:20px;top:50%;transform:translateY(-50%);\n    font-family:var(--mono);font-size:10px;letter-spacing:.12em;text-transform:uppercase;\n    background:var(--ink);color:#fff;padding:4px 9px;border-radius:6px;white-space:nowrap;\n    opacity:0;pointer-events:none;transition:.2s;\n  }\n  .rail a:hover span{opacity:1}\n  @media(max-width:1240px){.rail{display:none}}\n\n  /* ---------- HERO (terminal dark) ---------- */\n  .hero{position:relative;min-height:100svh;display:flex;align-items:center;overflow:hidden;padding-top:64px;background:var(--tl-ink);color:var(--tl-bone)}\n  #net{position:absolute;inset:0;width:100%;height:100%;z-index:0}\n  .hero-glow{position:absolute;z-index:0;width:940px;height:940px;border-radius:50%;right:-300px;top:-140px;\n    background:radial-gradient(circle at 62% 42%, rgba(74,134,247,.14), transparent 55%),radial-gradient(circle, rgba(74,134,247,.10), rgba(74,134,247,0) 62%);\n    filter:blur(22px);pointer-events:none}\n  .hero-fade{position:absolute;inset:0;z-index:1;pointer-events:none;\n    background:linear-gradient(to bottom, rgba(10,17,32,.18) 55%, var(--tl-ink) 100%),\n               linear-gradient(100deg, rgba(10,17,32,.88) 0%, rgba(10,17,32,.45) 45%, rgba(10,17,32,.08) 75%, rgba(10,17,32,.35) 100%)}\n  .hero-in{position:relative;z-index:2;width:100%}\n  .hero-grid{max-width:790px}\n  .coords{font-family:var(--mono);font-size:9.5px;letter-spacing:.22em;text-transform:uppercase;color:var(--tl-muted)}\n  .coords .dot{color:var(--tl-amber)}\n  .hero .tag{display:inline-flex;align-items:center;gap:10px;border:1px solid var(--tl-line);background:rgba(16,26,48,.55);padding:7px 14px;border-radius:999px;margin-bottom:30px}\n  .hero .tag .pip{width:7px;height:7px;border-radius:50%;background:var(--tl-accent);box-shadow:0 0 10px var(--tl-accent)}\n  .hero .tag span{font-size:12px;color:var(--tl-muted);letter-spacing:.04em}\n  .hero h1{font-size:clamp(42px,7.2vw,88px);margin-bottom:26px;color:var(--tl-bone)}\n  .hero h1 .l2{color:var(--tl-accent)}\n  .hero p.sub{font-size:clamp(16px,2vw,19px);color:var(--tl-muted);max-width:600px;margin-bottom:38px;line-height:1.6}\n  .hero p.sub strong{color:var(--tl-bone);font-weight:600}\n  .hero-cta{display:flex;gap:14px;flex-wrap:wrap;align-items:center}\n  .hero .btn-ghost{border-color:var(--tl-line2);color:var(--tl-bone)}\n  .hero .btn-ghost:hover{border-color:var(--tl-accent);color:var(--tl-accent2)}\n  .hero-meta{display:flex;gap:38px;margin-top:56px;flex-wrap:wrap}\n  .hero-meta .m b{display:block;font-size:34px;font-weight:800;letter-spacing:-.02em;color:var(--tl-accent2);font-family:var(--mono)}\n  .hero-meta .m span{font-size:12px;color:var(--tl-muted);letter-spacing:.05em}\n  .scroll-hint{position:absolute;bottom:24px;left:50%;transform:translateX(-50%);z-index:2;font-size:10.5px;letter-spacing:.3em;color:var(--tl-muted);text-transform:uppercase;font-family:var(--mono);opacity:.8}\n\n  /* ---------- ASKED TICKER ---------- */\n  .ticker{background:var(--tl-ink2);border-top:1px solid var(--tl-line);border-bottom:1px solid var(--tl-line);overflow:hidden;padding:16px 0}\n  .ticker .lane{display:flex;width:max-content;animation:tick 90s linear infinite;gap:0}\n  .ticker:hover .lane{animation-play-state:paused}\n  .ticker .q{font-family:var(--mono);font-size:12.5px;color:var(--tl-muted);white-space:nowrap;padding:0 14px;display:inline-flex;align-items:center;gap:14px}\n  .ticker .q b{color:var(--tl-bone);font-weight:400}\n  .ticker .q::after{content:\"·\";color:var(--tl-amber);margin-left:14px}\n  @keyframes tick{from{transform:translateX(0)}to{transform:translateX(-50%)}}\n\n  /* ---------- SECTION SHELL ---------- */\n  section{position:relative;padding:104px 0}\n  .sec-head{max-width:720px;margin-bottom:56px}\n  .sec-head.center{margin-left:auto;margin-right:auto;text-align:center}\n  .sec-head h2{font-size:clamp(30px,4.2vw,48px);margin:16px 0 18px}\n  .sec-head p{font-size:17.5px;color:var(--muted);line-height:1.6}\n  .sec-head p strong{color:var(--ink);font-weight:600}\n\n  /* ---------- SYSTEMS / INTEGRATIONS ---------- */\n  .systems{background:var(--bg)}\n  .sys-modes{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-bottom:54px}\n  .mode{border:1px solid var(--line);border-radius:var(--r);background:var(--surface);padding:28px;box-shadow:var(--shadow)}\n  .mode .mhead{display:flex;align-items:center;gap:12px;margin-bottom:12px}\n  .mode .mic{width:40px;height:40px;border-radius:10px;display:grid;place-items:center;background:var(--blue-soft);border:1px solid var(--blue-tint);flex:0 0 auto}\n  .mode .mic svg{width:20px;height:20px;stroke:var(--blue)}\n  .mode h3{font-size:18px}\n  .mode .mtag{font-family:var(--mono);font-size:10px;letter-spacing:.16em;text-transform:uppercase;color:var(--blue);background:var(--blue-soft);border-radius:5px;padding:3px 8px;margin-left:auto}\n  .mode p{font-size:14.5px;color:var(--muted);line-height:1.6}\n  .mode p b{color:var(--ink);font-weight:600}\n  .src-groups{display:grid;grid-template-columns:repeat(4,1fr);gap:30px 24px}\n  .src-cat h5{font-size:10.5px;letter-spacing:.18em;text-transform:uppercase;color:var(--blue);font-family:var(--mono);margin-bottom:13px;display:flex;align-items:center;gap:8px}\n  .src-cat h5::before{content:\"\";width:5px;height:5px;border-radius:50%;background:var(--blue)}\n  .src-cat .chips{display:flex;flex-wrap:wrap;gap:7px}\n  .src-cat .chips span{font-size:12.5px;color:var(--muted);border:1px solid var(--line);background:var(--surface);border-radius:999px;padding:4px 11px;transition:.2s;white-space:nowrap}\n  .src-cat .chips span:hover{border-color:var(--blue);color:var(--ink)}\n  .src-foot{text-align:center;margin-top:40px;font-size:14.5px;color:var(--muted)}\n  .src-foot a{color:var(--blue);font-weight:700}\n  .src-foot a:hover{color:var(--blue-press)}\n\n  /* ---------- PROBLEM ---------- */\n  .problem{background:var(--bg2);border-top:1px solid var(--line);border-bottom:1px solid var(--line)}\n  .prob-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}\n  .prob-card{border:1px solid var(--line);border-radius:var(--r);padding:28px;background:var(--surface);box-shadow:var(--shadow);transition:.25s}\n  .prob-card:hover{transform:translateY(-3px);box-shadow:var(--shadow-lift)}\n  .prob-card .n{font-family:var(--mono);color:var(--blue);font-size:12px;margin-bottom:16px;letter-spacing:.1em}\n  .prob-card h3{font-size:19px;margin-bottom:10px}\n  .prob-card p{font-size:14.5px;color:var(--muted);line-height:1.6}\n\n  /* ---------- HOW (3 layers) ---------- */\n  .how{background:var(--bg)}\n  .layers{display:grid;grid-template-columns:1fr;gap:16px;max-width:980px;margin:0 auto}\n  .layer{display:grid;grid-template-columns:118px 1fr;gap:30px;align-items:center;border:1px solid var(--line);border-radius:var(--r);padding:32px;background:var(--surface);box-shadow:var(--shadow);transition:.25s}\n  .layer:hover{box-shadow:var(--shadow-lift)}\n  .layer .lnum{font-family:var(--mono);font-size:12px;color:var(--blue);letter-spacing:.12em}\n  .layer .lnum b{display:block;font-size:46px;color:var(--ink);font-weight:800;letter-spacing:-.02em;margin-top:6px;line-height:1}\n  .layer h3{font-size:21px;margin-bottom:9px}\n  .layer p{color:var(--muted);font-size:15px;max-width:580px;line-height:1.6}\n  .layer p b{color:var(--ink);font-weight:600}\n  .layer .lpill{display:inline-block;font-size:11px;font-family:var(--mono);color:var(--blue);border:1px solid var(--blue-tint);background:var(--blue-soft);padding:4px 10px;border-radius:6px;margin-top:13px;letter-spacing:.04em}\n  .flowline{height:24px;width:1px;background:linear-gradient(var(--blue),transparent);margin:0 auto;opacity:.5}\n\n  /* ---------- IN PRODUCTION (Yoda + Nova) ---------- */\n  .production{background:var(--tl-ink);color:var(--tl-bone)}\n  .production .sec-head p{color:var(--tl-muted)}\n  .production .sec-head p strong{color:var(--tl-bone)}\n  .prod-grid{display:grid;grid-template-columns:1fr 1fr;gap:22px}\n  .prod{border:1px solid var(--tl-line);border-radius:var(--r);background:var(--tl-panel);padding:32px;position:relative;overflow:hidden}\n  .prod::before{content:\"\";position:absolute;inset:0;background:radial-gradient(circle at 100% 0,rgba(74,134,247,.10),transparent 55%);pointer-events:none}\n  .prod .phead{display:flex;align-items:center;gap:13px;margin-bottom:6px;position:relative}\n  .prod .pic{width:44px;height:44px;border-radius:11px;display:grid;place-items:center;background:rgba(74,134,247,.12);border:1px solid var(--tl-line2);flex:0 0 auto}\n  .prod .pic svg{width:22px;height:22px;stroke:var(--tl-accent2)}\n  .prod h3{font-size:23px;color:var(--tl-bone)}\n  .prod .ptag{font-family:var(--mono);font-size:10px;letter-spacing:.16em;text-transform:uppercase;color:var(--tl-amber);border:1px solid rgba(199,167,108,.35);border-radius:5px;padding:3px 9px;margin-left:auto;white-space:nowrap}\n  .prod .psub{font-family:var(--mono);font-size:11.5px;color:var(--tl-muted);letter-spacing:.06em;margin-bottom:16px;position:relative}\n  .prod > p{font-size:14.5px;color:var(--tl-muted);line-height:1.65;margin-bottom:16px;position:relative}\n  .prod > p b{color:var(--tl-bone);font-weight:600}\n  .prod ul{list-style:none;display:grid;gap:9px;position:relative;margin-bottom:18px}\n  .prod ul li{font-size:13.5px;color:var(--tl-muted);display:flex;gap:9px;align-items:flex-start;line-height:1.5}\n  .prod ul li::before{content:\"→\";color:var(--tl-accent);flex:0 0 auto}\n  .prod ul li b{color:var(--tl-bone);font-weight:600}\n  .prod .translate{border-top:1px solid var(--tl-line);padding-top:16px;position:relative}\n  .prod .translate .tlabel{font-family:var(--mono);font-size:10px;letter-spacing:.18em;text-transform:uppercase;color:var(--tl-accent2);margin-bottom:8px}\n  .prod .translate p{font-size:14px;color:var(--tl-muted);line-height:1.6}\n  .prod .translate p b{color:var(--tl-bone);font-weight:600}\n  .prod-foot{margin-top:26px;text-align:center;font-size:14.5px;color:var(--tl-muted)}\n  .prod-foot b{color:var(--tl-bone);font-weight:600}\n\n  /* ---------- SHOWCASE TERMINALS ---------- */\n  .showcase{background:var(--bg)}\n  .show-grid{display:grid;grid-template-columns:1fr 1fr;gap:52px;align-items:center}\n  .show-copy h2{font-size:clamp(28px,3.8vw,42px);margin:16px 0 20px}\n  .show-copy p{color:var(--muted);font-size:16.5px;margin-bottom:16px;line-height:1.6}\n  .show-copy p strong{color:var(--ink);font-weight:600}\n  .show-list{list-style:none;margin-top:24px;display:grid;gap:13px}\n  .show-list li{display:flex;gap:12px;align-items:flex-start;font-size:14.5px}\n  .show-list li svg{flex:0 0 auto;width:19px;height:19px;stroke:var(--blue);margin-top:2px}\n  .show-list li span{color:var(--muted);line-height:1.55}\n  .show-list li span em{color:var(--ink);font-style:normal;font-weight:600}\n  .term-stack{display:grid;gap:18px}\n  .terminal{border:1px solid var(--tl-line2);border-radius:14px;background:linear-gradient(180deg,var(--tl-panel),var(--tl-ink2));overflow:hidden;box-shadow:0 30px 80px -40px rgba(10,17,32,.55)}\n  .term-bar{display:flex;align-items:center;gap:7px;padding:12px 16px;border-bottom:1px solid var(--tl-line);background:rgba(10,17,32,.45)}\n  .term-bar i{width:10px;height:10px;border-radius:50%;display:block}\n  .term-bar i:nth-child(1){background:#b1503f}.term-bar i:nth-child(2){background:#b98a36}.term-bar i:nth-child(3){background:#4f7d5d}\n  .term-bar span{margin-left:10px;font-family:var(--mono);font-size:11.5px;color:var(--tl-muted)}\n  .term-body{padding:20px 22px;font-family:var(--mono);font-size:12.5px;line-height:1.8;color:var(--tl-bone)}\n  .term-body .q{color:var(--tl-accent2)}\n  .term-body .a{color:var(--tl-bone)}\n  .term-body .cite{color:var(--tl-accent)}\n  .term-body .dim{color:var(--tl-muted)}\n  .term-body .ok{color:#7dba8c}\n  .term-body .amber{color:var(--tl-amber)}\n\n  /* ---------- FIELD NOTES ---------- */\n  .notes{background:var(--bg2);border-top:1px solid var(--line);border-bottom:1px solid var(--line)}\n  .note-cols{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}\n  .note-col{display:grid;gap:20px;align-content:start}\n  .note-group{border:1px solid var(--line);border-radius:var(--r);background:var(--surface);padding:24px;box-shadow:var(--shadow)}\n  .note-group h4{font-family:var(--mono);font-size:10.5px;letter-spacing:.18em;text-transform:uppercase;color:var(--blue);margin-bottom:14px;display:flex;align-items:center;gap:8px}\n  .note-group h4::before{content:\"\";width:5px;height:5px;border-radius:50%;background:var(--blue)}\n  .note-group ul{list-style:none;display:grid;gap:11px}\n  .note-group li{font-size:13.5px;color:var(--muted);line-height:1.55;display:flex;gap:9px;align-items:flex-start}\n  .note-group li::before{content:\"—\";color:var(--blue);flex:0 0 auto}\n  .note-group li b{color:var(--ink);font-weight:600}\n  .notes-foot{text-align:center;margin-top:36px;font-size:14px;color:var(--muted)}\n\n  /* ---------- FEATURES ---------- */\n  .features{background:var(--bg)}\n  .feat-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}\n  .feat{border:1px solid var(--line);border-radius:var(--r);padding:26px;background:var(--surface);box-shadow:var(--shadow);transition:.25s;position:relative}\n  .feat:hover{border-color:var(--blue-tint);transform:translateY(-3px);box-shadow:var(--shadow-lift)}\n  .feat .ic{width:42px;height:42px;border-radius:10px;display:grid;place-items:center;background:var(--blue-soft);border:1px solid var(--blue-tint);margin-bottom:18px}\n  .feat .ic svg{width:21px;height:21px;stroke:var(--blue)}\n  .feat h3{font-size:17px;margin-bottom:8px}\n  .feat p{font-size:14px;color:var(--muted);line-height:1.6}\n  .feat .fex{margin-top:12px;padding-top:12px;border-top:1px dashed var(--line);font-size:12.5px;color:var(--muted2);line-height:1.5;font-family:var(--mono)}\n  .feat .fex b{color:var(--muted);font-weight:400}\n\n  /* ---------- INDUSTRIES ---------- */\n  .industries{background:var(--bg2);border-top:1px solid var(--line);border-bottom:1px solid var(--line)}\n  .ind-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}\n  .ind{border:1px solid var(--line);border-radius:var(--r);padding:26px;background:var(--surface);box-shadow:var(--shadow);transition:.28s;position:relative;overflow:hidden}\n  .ind::before{content:\"\";position:absolute;inset:0;background:radial-gradient(circle at 100% 0,var(--blue-soft),transparent 55%);opacity:0;transition:.3s}\n  .ind:hover{transform:translateY(-4px);box-shadow:var(--shadow-lift)}\n  .ind:hover::before{opacity:1}\n  .ind .ihead{display:flex;align-items:center;gap:12px;margin-bottom:14px;position:relative}\n  .ind .iic{width:40px;height:40px;border-radius:10px;display:grid;place-items:center;background:var(--bg2);border:1px solid var(--line);flex:0 0 auto}\n  .ind .iic svg{width:20px;height:20px;stroke:var(--blue)}\n  .ind h3{font-size:17px;position:relative}\n  .ind p{font-size:13.5px;color:var(--muted);line-height:1.55;position:relative;margin-bottom:13px}\n  .ind ul{list-style:none;position:relative;display:grid;gap:6px}\n  .ind ul li{font-size:12.5px;color:var(--muted);display:flex;gap:8px;align-items:flex-start;line-height:1.5}\n  .ind ul li::before{content:\"→\";color:var(--blue);flex:0 0 auto}\n\n  /* ---------- VERSUS ---------- */\n  .versus{background:var(--bg)}\n  .cmp{display:grid;grid-template-columns:1fr 1fr;gap:0;border:1px solid var(--line);border-radius:var(--r);overflow:hidden;max-width:960px;margin:0 auto;box-shadow:var(--shadow)}\n  .cmp .col{padding:36px}\n  .cmp .col.them{background:var(--bg2);border-right:1px solid var(--line)}\n  .cmp .col.us{background:linear-gradient(180deg,var(--blue-soft),var(--surface) 55%)}\n  .cmp h3{font-size:14px;letter-spacing:.04em;margin-bottom:22px;display:flex;align-items:center;gap:10px}\n  .cmp .col.them h3{color:var(--muted)}\n  .cmp .col.us h3{color:var(--blue)}\n  .cmp ul{list-style:none;display:grid;gap:15px}\n  .cmp li{display:flex;gap:12px;font-size:14px;align-items:flex-start;line-height:1.5}\n  .cmp li svg{flex:0 0 auto;width:17px;height:17px;margin-top:2px}\n  .cmp .them li{color:var(--muted)}\n  .cmp .them li svg{stroke:var(--bad)}\n  .cmp .us li{color:var(--ink)}\n  .cmp .us li svg{stroke:var(--good)}\n\n  /* ---------- SECURITY ---------- */\n  .deploy{background:var(--bg2);border-top:1px solid var(--line)}\n  .dep-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:18px;margin-bottom:64px}\n  .dep{border:1px solid var(--line);border-radius:var(--r);padding:24px;background:var(--surface);box-shadow:var(--shadow)}\n  .dep .ic{width:38px;height:38px;border-radius:10px;display:grid;place-items:center;background:var(--blue-soft);border:1px solid var(--blue-tint);margin-bottom:14px}\n  .dep .ic svg{width:19px;height:19px;stroke:var(--blue)}\n  .dep h3{font-size:15.5px;margin-bottom:7px}\n  .dep p{font-size:13px;color:var(--muted);line-height:1.55}\n  .expert-grid{display:grid;grid-template-columns:1.05fr .95fr;gap:56px;align-items:center}\n  .expert-copy h2{font-size:clamp(26px,3.6vw,42px);margin:16px 0 18px}\n  .expert-copy>p{color:var(--muted);font-size:16px;line-height:1.6;margin-bottom:30px;max-width:540px}\n  .pillars{display:grid;gap:20px}\n  .pillar{display:flex;gap:15px;align-items:flex-start}\n  .pillar .pic2{flex:0 0 auto;width:42px;height:42px;border-radius:10px;display:grid;place-items:center;background:var(--blue-soft);border:1px solid var(--blue-tint)}\n  .pillar .pic2 svg{width:21px;height:21px;stroke:var(--blue)}\n  .pillar h4{font-size:15.5px;font-weight:700;margin-bottom:4px}\n  .pillar p{font-size:14px;color:var(--muted);line-height:1.55;max-width:430px}\n  .sec-panel{border:1px solid var(--tl-line2);border-radius:16px;background:linear-gradient(180deg,var(--tl-panel),var(--tl-ink2));padding:30px;box-shadow:0 30px 80px -45px rgba(10,17,32,.6);color:var(--tl-bone)}\n  .sec-panel .sp-top{display:flex;align-items:center;gap:13px;padding-bottom:18px;margin-bottom:20px;border-bottom:1px solid var(--tl-line)}\n  .sec-panel .sp-top .shield{width:42px;height:42px;border-radius:11px;display:grid;place-items:center;background:radial-gradient(circle at 30% 25%,var(--tl-accent2),var(--blue) 60%,var(--blue-press));box-shadow:0 0 22px rgba(74,134,247,.35);flex:0 0 auto}\n  .sec-panel .sp-top .shield svg{width:21px;height:21px;stroke:#fff}\n  .sec-panel .sp-top h4{font-size:15.5px;font-weight:700}\n  .sec-panel .sp-top span{font-size:12.5px;color:var(--tl-muted);display:block;margin-top:2px}\n  .sec-checks{display:grid;gap:13px}\n  .sec-checks li{display:flex;gap:11px;align-items:flex-start;font-size:13.5px;list-style:none;line-height:1.5}\n  .sec-checks li svg{flex:0 0 auto;width:17px;height:17px;stroke:var(--tl-accent);margin-top:2px}\n  .sec-checks li b{font-weight:600;color:var(--tl-bone)}\n  .sec-checks li span{color:var(--tl-muted)}\n  .sec-foot{margin-top:22px;padding-top:18px;border-top:1px solid var(--tl-line)}\n  .sec-foot .nt{display:inline-flex;align-items:center;gap:9px;font-size:12.5px;color:var(--tl-amber);font-weight:600;border:1px solid rgba(199,167,108,.3);background:rgba(199,167,108,.08);padding:8px 14px;border-radius:999px}\n  .sec-foot .nt svg{width:15px;height:15px;stroke:var(--tl-amber)}\n\n  /* ---------- STATS BAND ---------- */\n  .band{background:var(--tl-ink);border-top:1px solid var(--tl-line)}\n  .band .wrap{display:grid;grid-template-columns:repeat(4,1fr);gap:30px;padding-top:64px;padding-bottom:64px}\n  .stat{text-align:center}\n  .stat b{display:block;font-size:50px;font-weight:800;letter-spacing:-.02em;font-family:var(--mono);color:var(--tl-accent2)}\n  .stat span{font-size:13px;color:var(--tl-muted)}\n\n  /* ---------- QUOTE ---------- */\n  .quote{background:var(--bg);text-align:center}\n  .quote blockquote{max-width:880px;margin:0 auto;font-size:clamp(24px,3.4vw,38px);font-weight:700;letter-spacing:-.02em;line-height:1.3}\n  .quote blockquote .blue{font-weight:700}\n  .quote .qattr{margin-top:28px;color:var(--muted);font-size:14px}\n  .quote .qmark{font-size:76px;color:var(--blue);line-height:.4;font-family:Georgia,serif;opacity:.35}\n\n  /* ---------- FAQ ---------- */\n  .faq{background:var(--bg2);border-top:1px solid var(--line)}\n  .faq-list{max-width:840px;margin:0 auto;border:1px solid var(--line);border-radius:var(--r);background:var(--surface);box-shadow:var(--shadow);overflow:hidden}\n  .qa{border-bottom:1px solid var(--line)}\n  .qa:last-child{border-bottom:0}\n  .qa button{width:100%;background:none;border:0;color:var(--ink);text-align:left;display:flex;justify-content:space-between;gap:20px;align-items:center;padding:22px 26px;cursor:pointer;font-size:16.5px;font-weight:700;font-family:inherit;letter-spacing:-.01em}\n  .qa button .pm{flex:0 0 auto;width:24px;height:24px;display:grid;place-items:center;border:1px solid var(--line2);border-radius:50%;color:var(--blue);transition:.25s;font-size:17px;font-weight:400}\n  .qa.open button .pm{transform:rotate(45deg);background:var(--blue);color:#fff;border-color:var(--blue)}\n  .qa .ans{max-height:0;overflow:hidden;transition:max-height .3s ease;color:var(--muted);font-size:15px;line-height:1.6}\n  .qa .ans p{padding:0 26px 24px;max-width:720px}\n  .qa .ans p b{color:var(--ink);font-weight:600}\n\n  /* ---------- CTA ---------- */\n  .cta{position:relative;overflow:hidden;background:var(--tl-ink);text-align:center;padding:130px 0;color:var(--tl-bone)}\n  .cta .glow{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:820px;height:820px;border-radius:50%;background:radial-gradient(circle,rgba(74,134,247,.16),transparent 60%);filter:blur(30px)}\n  .cta-in{position:relative;z-index:2}\n  .cta h2{font-size:clamp(36px,5.6vw,68px);margin:20px auto 22px;max-width:820px;color:var(--tl-bone)}\n  .cta h2 .blue{color:var(--tl-accent);display:block}\n  .cta p{color:var(--tl-muted);font-size:18px;max-width:560px;margin:0 auto 36px}\n  .cta-row{display:flex;gap:14px;justify-content:center;flex-wrap:wrap}\n  .cta .btn-ghost{border-color:var(--tl-line2);color:var(--tl-bone)}\n  .cta .btn-ghost:hover{border-color:var(--tl-accent);color:var(--tl-accent2)}\n  .cta .fine{margin-top:24px;font-size:12.5px;color:var(--tl-muted);font-family:var(--mono);letter-spacing:.04em}\n\n  /* ---------- FOOTER ---------- */\n  footer{background:var(--tl-ink2);border-top:1px solid var(--tl-line);padding:60px 0 36px;color:var(--tl-bone)}\n  footer .brand .bprod{color:var(--tl-accent)}\n  footer .brand .bdiv{background:var(--tl-line2)}\n  .foot-grid{display:grid;grid-template-columns:1.6fr 1fr 1fr 1fr;gap:40px;margin-bottom:44px}\n  .foot-brand p{color:var(--tl-muted);font-size:13.5px;margin-top:16px;max-width:300px;line-height:1.6}\n  .foot-col h4{font-size:11px;letter-spacing:.16em;text-transform:uppercase;color:var(--tl-muted);margin-bottom:16px;font-family:var(--mono)}\n  .foot-col a{display:block;color:var(--tl-muted);font-size:13.5px;margin-bottom:11px;transition:.2s}\n  .foot-col a:hover{color:var(--tl-accent2)}\n  .foot-bot{display:flex;justify-content:space-between;align-items:center;border-top:1px solid var(--tl-line);padding-top:24px;flex-wrap:wrap;gap:16px}\n  .foot-bot p{color:var(--tl-muted);font-size:12.5px}\n\n  /* reveal */\n  .reveal{opacity:0;transform:translateY(22px);transition:opacity .7s cubic-bezier(.2,.7,.2,1),transform .7s cubic-bezier(.2,.7,.2,1)}\n  .reveal.in{opacity:1;transform:none}\n  @media(prefers-reduced-motion:reduce){.reveal{opacity:1;transform:none;transition:none}.ticker .lane{animation:none}}\n\n  /* ---------- RESPONSIVE ---------- */\n  @media(max-width:980px){\n    .prob-grid,.feat-grid,.ind-grid,.note-cols{grid-template-columns:1fr 1fr}\n    .src-groups{grid-template-columns:1fr 1fr}\n    .dep-grid{grid-template-columns:1fr 1fr}\n    .show-grid,.expert-grid,.prod-grid,.sys-modes{grid-template-columns:1fr;gap:34px}\n    .band .wrap{grid-template-columns:1fr 1fr;gap:36px}\n  }\n  @media(max-width:680px){\n    .nav-links{display:none}\n    .prob-grid,.feat-grid,.ind-grid,.dep-grid,.cmp,.src-groups,.note-cols{grid-template-columns:1fr}\n    .cmp .col.them{border-right:0;border-bottom:1px solid var(--line)}\n    .layer{grid-template-columns:1fr;gap:14px}\n    .layer .lnum b{font-size:34px}\n    section{padding:74px 0}\n    .hero-meta{gap:24px}\n    .nav-cta .btn-ghost{display:none}\n    .foot-grid{grid-template-columns:1fr 1fr}\n  }\n</style>\n</head>\n<body>\n\n<div class=\"progress\" id=\"progress\"></div>\n\n<!-- NAV -->\n<header class=\"nav\" id=\"nav\">\n  <div class=\"nav-in\">\n    <a href=\"#top\" class=\"brand\" data-jump aria-label=\"Endurance AI Labs — Brain\">\n      <img src=\"/logo-endurance-white.svg\" alt=\"Endurance AI Labs\" class=\"wordmark wm-light\" />\n      <img src=\"/logo-endurance.svg\" alt=\"\" aria-hidden=\"true\" class=\"wordmark wm-dark\" />\n      <span class=\"bdiv\"></span>\n      <span class=\"bprod\">Brain</span>\n    </a>\n    <nav class=\"nav-links\" id=\"navlinks\">\n      <a href=\"#systems\" data-jump>Integrations</a>\n      <a href=\"#how\" data-jump>How it works</a>\n      <a href=\"#production\" data-jump>In production</a>\n      <a href=\"#features\" data-jump>Capabilities</a>\n      <a href=\"#industries\" data-jump>Industries</a>\n      <a href=\"#security\" data-jump>Security</a>\n      <a href=\"#faq\" data-jump>FAQ</a>\n      <a href=\"/brain/reel\" class=\"nav-reel\">&#9654; Watch the reel</a>\n    </nav>\n    <div class=\"nav-cta\">\n      <a href=\"#\" data-demo class=\"btn btn-ghost\">Book a demo</a>\n      <a href=\"#cta\" data-jump class=\"btn btn-blue\">Get started</a>\n    </div>\n  </div>\n</header>\n\n<!-- DOT RAIL -->\n<nav class=\"rail dark\" id=\"rail\" aria-label=\"Section navigation\">\n  <a href=\"#top\" data-jump data-sec=\"top\"><span>Top</span></a>\n  <a href=\"#systems\" data-jump data-sec=\"systems\"><span>Integrations</span></a>\n  <a href=\"#how\" data-jump data-sec=\"how\"><span>How it works</span></a>\n  <a href=\"#production\" data-jump data-sec=\"production\"><span>In production</span></a>\n  <a href=\"#notes\" data-jump data-sec=\"notes\"><span>Field notes</span></a>\n  <a href=\"#features\" data-jump data-sec=\"features\"><span>Capabilities</span></a>\n  <a href=\"#industries\" data-jump data-sec=\"industries\"><span>Industries</span></a>\n  <a href=\"#security\" data-jump data-sec=\"security\"><span>Security</span></a>\n  <a href=\"#faq\" data-jump data-sec=\"faq\"><span>FAQ</span></a>\n  <a href=\"#cta\" data-jump data-sec=\"cta\"><span>Get started</span></a>\n</nav>\n\n<!-- HERO -->\n<section class=\"hero\" id=\"top\" style=\"padding-top:64px\">\n  <canvas id=\"net\"></canvas>\n  <div class=\"hero-glow\"></div>\n  <div class=\"hero-fade\"></div>\n  <div class=\"hero-in\">\n    <div class=\"wrap\">\n      <div class=\"hero-grid\">\n        <p class=\"coords\" style=\"margin-bottom:20px\">68&deg;44&prime;21&Prime;S <span class=\"dot\">&middot;</span> 52&deg;19&prime;47&Prime;W &mdash; Endurance, found intact after 107 years</p>\n        <span class=\"tag\"><span class=\"pip\"></span><span>Institutional memory &middot; proven in production &middot; Endurance AI Labs</span></span>\n        <h1>Institutional memory,<br><span class=\"l2\">finally autonomous.</span></h1>\n        <p class=\"sub\">Every email, message, document, meeting, deal, shipment, and line of code your firm produces flows into a living knowledge base that <strong>maintains itself</strong> — connected to every system you run, answering any question with <strong>cited, verifiable</strong> sources. No more knowledge walking out the door.</p>\n        <div class=\"hero-cta\">\n          <a href=\"#cta\" data-jump class=\"btn btn-blue\">Deploy your Brain &nbsp;&rarr;</a>\n          <a href=\"#how\" data-jump class=\"btn btn-ghost\">See how it works</a>\n        </div>\n        <div class=\"hero-meta\">\n          <div class=\"m\"><b>40+</b><span>systems it connects to</span></div>\n          <div class=\"m\"><b>100%</b><span>cited — zero hallucination</span></div>\n          <div class=\"m\"><b>2</b><span>brains live in production</span></div>\n          <div class=\"m\"><b>24/7</b><span>self-maintaining</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"scroll-hint\">scroll &darr;</div>\n</section>\n\n<!-- ASKED &amp; ANSWERED TICKER -->\n<div class=\"ticker\" aria-label=\"Real questions teams ask their Brain\">\n  <div class=\"lane\" id=\"tickerlane\">\n    <span class=\"q\"><b>&ldquo;Who owns the billing service?&rdquo;</b> answered with the deciding thread + 3 citations</span>\n    <span class=\"q\"><b>&ldquo;What&rsquo;s this customer&rsquo;s margin history?&rdquo;</b> pulled live from the TMS, mid-chat</span>\n    <span class=\"q\"><b>&ldquo;Why did we pass on that deal in 2024?&rdquo;</b> the IC thread nobody could find, in seconds</span>\n    <span class=\"q\"><b>&ldquo;What did legal say about the sublease?&rdquo;</b> the exact email, one click away</span>\n    <span class=\"q\"><b>&ldquo;Which carriers failed on this lane last quarter?&rdquo;</b> incident threads attached</span>\n    <span class=\"q\"><b>&ldquo;What changed in the data room overnight?&rdquo;</b> a diff, not a re-read</span>\n    <span class=\"q\"><b>&ldquo;Who&rsquo;s touched the payments code?&rdquo;</b> every PR, review, and commit — cited</span>\n    <span class=\"q\"><b>&ldquo;What&rsquo;s our commission rule when margin drops below the gate?&rdquo;</b> cited to the policy page</span>\n    <span class=\"q\"><b>&ldquo;Where&rsquo;s the latest signed MSA?&rdquo;</b> found across 4 systems in one ask</span>\n    <span class=\"q\"><b>&ldquo;What did we promise this client in March?&rdquo;</b> the thread, the doc, and the call transcript</span>\n    <span class=\"q\"><b>&ldquo;Who owns the billing service?&rdquo;</b> answered with the deciding thread + 3 citations</span>\n    <span class=\"q\"><b>&ldquo;What&rsquo;s this customer&rsquo;s margin history?&rdquo;</b> pulled live from the TMS, mid-chat</span>\n    <span class=\"q\"><b>&ldquo;Why did we pass on that deal in 2024?&rdquo;</b> the IC thread nobody could find, in seconds</span>\n    <span class=\"q\"><b>&ldquo;What did legal say about the sublease?&rdquo;</b> the exact email, one click away</span>\n    <span class=\"q\"><b>&ldquo;Which carriers failed on this lane last quarter?&rdquo;</b> incident threads attached</span>\n    <span class=\"q\"><b>&ldquo;What changed in the data room overnight?&rdquo;</b> a diff, not a re-read</span>\n    <span class=\"q\"><b>&ldquo;Who&rsquo;s touched the payments code?&rdquo;</b> every PR, review, and commit — cited</span>\n    <span class=\"q\"><b>&ldquo;What&rsquo;s our commission rule when margin drops below the gate?&rdquo;</b> cited to the policy page</span>\n    <span class=\"q\"><b>&ldquo;Where&rsquo;s the latest signed MSA?&rdquo;</b> found across 4 systems in one ask</span>\n    <span class=\"q\"><b>&ldquo;What did we promise this client in March?&rdquo;</b> the thread, the doc, and the call transcript</span>\n  </div>\n</div>\n\n<!-- SYSTEMS / INTEGRATIONS -->\n<section class=\"systems\" id=\"systems\">\n  <div class=\"wrap\">\n    <div class=\"sec-head center reveal\">\n      <span class=\"eyebrow\"><span class=\"dot\">&#9679;</span> Connected to everything</span>\n      <h2>One brain. Wired into every system you run.</h2>\n      <p>The Brain doesn&rsquo;t live beside your stack — it&rsquo;s plumbed into it. Two kinds of connection, working together: <strong>synced</strong> sources ingested continuously into an immutable record, and <strong>live</strong> reads against your systems of record at the moment you ask.</p>\n    </div>\n\n    <div class=\"sys-modes\">\n      <div class=\"mode reveal\">\n        <div class=\"mhead\">\n          <span class=\"mic\"><svg fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-refresh\"/></svg></span>\n          <h3>Synced — the permanent record</h3>\n          <span class=\"mtag\">Cron &middot; 24/7</span>\n        </div>\n        <p>Scheduled connectors pull email, chat, documents, tickets, meetings, and code into <b>immutable raw sources</b> around the clock, then re-compile the wiki on top. Nothing is paraphrased away — the original is preserved verbatim, forever, and every synthesized claim links back to it.</p>\n      </div>\n      <div class=\"mode reveal\">\n        <div class=\"mhead\">\n          <span class=\"mic\"><svg fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-bolt\"/></svg></span>\n          <h3>Live — current to the second</h3>\n          <span class=\"mtag\">MCP &middot; at answer time</span>\n        </div>\n        <p>Some answers can&rsquo;t be a day old. Through <b>live tool connections (MCP)</b>, the Brain queries your system of record — the TMS, the CRM, the ERP — while it answers. Ask about a load, an account, an invoice: it reads the live record and cites it, with your system of record treated as <b>ground truth</b> by rule.</p>\n      </div>\n    </div>\n\n    <div class=\"src-groups\">\n      <div class=\"src-cat reveal\">\n        <h5>Communication</h5>\n        <div class=\"chips\">\n          <span>Outlook / Exchange</span><span>Gmail &amp; Google Groups</span><span>Slack</span>\n          <span>Microsoft Teams</span><span>SMS &amp; WhatsApp Business</span><span>Intercom</span><span>RingCentral</span>\n        </div>\n      </div>\n      <div class=\"src-cat reveal\">\n        <h5>Documents &amp; Files</h5>\n        <div class=\"chips\">\n          <span>Google Drive &amp; Docs</span><span>SharePoint &amp; OneDrive</span><span>Box</span><span>Dropbox</span>\n          <span>Egnyte</span><span>Network file shares</span><span>PDFs &amp; scans</span><span>DocuSign &amp; e-sign</span>\n        </div>\n      </div>\n      <div class=\"src-cat reveal\">\n        <h5>Knowledge &amp; Wikis</h5>\n        <div class=\"chips\">\n          <span>Confluence</span><span>Notion</span><span>Guru</span><span>SharePoint wikis</span><span>Internal wikis</span>\n        </div>\n      </div>\n      <div class=\"src-cat reveal\">\n        <h5>Projects &amp; Tickets</h5>\n        <div class=\"chips\">\n          <span>Jira</span><span>Linear</span><span>Asana</span><span>Monday.com</span><span>ClickUp</span>\n          <span>Trello</span><span>ServiceNow</span><span>Zendesk</span>\n        </div>\n      </div>\n      <div class=\"src-cat reveal\">\n        <h5>Meetings &amp; Calls</h5>\n        <div class=\"chips\">\n          <span>Zoom transcripts</span><span>Google Meet</span><span>Teams meetings</span><span>Gong</span>\n          <span>Fireflies</span><span>Otter.ai</span><span>Calendars</span>\n        </div>\n      </div>\n      <div class=\"src-cat reveal\">\n        <h5>CRM &amp; Business Systems</h5>\n        <div class=\"chips\">\n          <span>Salesforce</span><span>HubSpot</span><span>Microsoft Dynamics</span><span>NetSuite / ERP</span>\n          <span>SAP &amp; Oracle</span><span>Airtable</span><span>QuickBooks</span><span>Xero</span>\n        </div>\n      </div>\n      <div class=\"src-cat reveal\">\n        <h5>Industry Systems of Record</h5>\n        <div class=\"chips\">\n          <span>McLeod &amp; TMS platforms</span><span>iManage</span><span>NetDocuments</span><span>Datasite</span>\n          <span>Intralinks</span><span>Procore</span><span>Yardi / RealPage / AppFolio</span><span>Virtual data rooms</span>\n        </div>\n      </div>\n      <div class=\"src-cat reveal\">\n        <h5>Code &amp; Data</h5>\n        <div class=\"chips\">\n          <span>GitHub</span><span>GitLab</span><span>Bitbucket</span><span>Azure DevOps</span>\n          <span>Postgres / SQL Server</span><span>Snowflake &amp; BigQuery</span><span>S3 &amp; object storage</span><span>Internal APIs &amp; webhooks</span>\n        </div>\n      </div>\n    </div>\n    <p class=\"src-foot reveal\">Don&rsquo;t see yours? <a href=\"#cta\" data-jump>If it has an API, the Brain plugs into it. If it doesn&rsquo;t, we build the connector &rarr;</a></p>\n  </div>\n</section>\n\n<!-- PROBLEM -->\n<section class=\"problem\" id=\"problem\">\n  <div class=\"wrap\">\n    <div class=\"sec-head reveal\">\n      <span class=\"eyebrow\"><span class=\"dot\">&#9679;</span> The problem</span>\n      <h2>Your firm&rsquo;s most valuable asset is its memory. And it&rsquo;s leaking.</h2>\n      <p>The context behind every deal, matter, shipment, and decision lives scattered across a dozen tools and a handful of people&rsquo;s heads. When they&rsquo;re busy, on PTO, or gone — that knowledge is gone with them.</p>\n    </div>\n    <div class=\"prob-grid\">\n      <div class=\"prob-card reveal\">\n        <div class=\"n\">01 / KNOWLEDGE SILOS</div>\n        <h3>Answers are buried</h3>\n        <p>The thread, the doc, the email, the meeting where it was actually decided — nobody can find it. Teams re-litigate solved problems weekly.</p>\n      </div>\n      <div class=\"prob-card reveal\">\n        <div class=\"n\">02 / TRIBAL KNOWLEDGE</div>\n        <h3>It walks out the door</h3>\n        <p>When a partner, PM, or senior associate leaves, years of context leaves with them. Onboarding the next hire takes months instead of days.</p>\n      </div>\n      <div class=\"prob-card reveal\">\n        <div class=\"n\">03 / AI YOU CAN&rsquo;T TRUST</div>\n        <h3>Chatbots that hallucinate</h3>\n        <p>Generic AI search confidently invents facts with no source. In law, finance, logistics, and real estate, an unverifiable answer is worse than none.</p>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- HOW IT WORKS -->\n<section class=\"how\" id=\"how\">\n  <div class=\"wrap\">\n    <div class=\"sec-head center reveal\">\n      <span class=\"eyebrow\"><span class=\"dot\">&#9679;</span> How it works</span>\n      <h2>Three layers. One compounding brain.</h2>\n      <p>Built on Andrej Karpathy&rsquo;s LLM-Wiki pattern — running in production today, not a science project. Raw truth at the bottom, living synthesis on top, a strict schema in between.</p>\n    </div>\n    <div class=\"layers\">\n      <div class=\"layer reveal\">\n        <div class=\"lnum\">LAYER<b>01</b></div>\n        <div>\n          <h3>Ingest — immutable raw sources</h3>\n          <p>Connectors pull from every tool your team uses and write into a permanent, tamper-proof record — Slack threads, tickets, transcripts, docs, commits, CRM records. The source of truth is <b>never overwritten or paraphrased</b>; it&rsquo;s preserved verbatim, forever, and regenerated by scheduled syncs.</p>\n          <span class=\"lpill\">Email &middot; Slack &middot; Teams &middot; Docs &middot; Jira &middot; Zoom &middot; Code &middot; CRM &middot; TMS</span>\n        </div>\n      </div>\n      <div class=\"flowline\"></div>\n      <div class=\"layer reveal\">\n        <div class=\"lnum\">LAYER<b>02</b></div>\n        <div>\n          <h3>Synthesize — the living wiki</h3>\n          <p>An LLM continuously maintains <b>entity pages</b> — one per person, client, deal, carrier, property, repo, project — and <b>synthesis pages</b>: expertise maps, onboarding guides, curated Q&amp;A. Every claim is backed by a citation to a raw source, <b>enforced by schema, not hope</b>. When sources disagree, an authority rule decides which system wins — and surfaces the conflict.</p>\n          <span class=\"lpill\">Entity pages &middot; Expertise maps &middot; Onboarding guides &middot; Citation-enforced</span>\n        </div>\n      </div>\n      <div class=\"flowline\"></div>\n      <div class=\"layer reveal\">\n        <div class=\"lnum\">LAYER<b>03</b></div>\n        <div>\n          <h3>Answer — ask in plain language</h3>\n          <p>Your team asks in Slack, Teams, or the web — the Brain answers from the compiled wiki with linked sources every time, and reaches into live systems when the answer must be current to the second. A <b>deterministic lint loop</b> hunts contradictions and stale facts on schedule, so the brain only gets sharper.</p>\n          <span class=\"lpill\">Slack &middot; Teams &middot; Web &middot; Live MCP tools &middot; Self-healing lint</span>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- IN PRODUCTION: YODA + NOVA -->\n<section class=\"production\" id=\"production\">\n  <div class=\"wrap\">\n    <div class=\"sec-head center reveal\">\n      <span class=\"eyebrow\" style=\"color:var(--tl-accent2)\"><span class=\"dot\">&#9679;</span> Not a demo — deployed</span>\n      <h2 style=\"color:var(--tl-bone)\">Two brains, live in production today.</h2>\n      <p>Endurance Brain isn&rsquo;t a concept deck. The same architecture runs every day inside two very different operations — an engineering organization and a freight brokerage — which is exactly the point: <strong>the pattern reshapes to any industry.</strong></p>\n    </div>\n    <div class=\"prod-grid\">\n\n      <div class=\"prod reveal\">\n        <div class=\"phead\">\n          <span class=\"pic\"><svg fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-cpu\"/></svg></span>\n          <h3>Yoda</h3>\n          <span class=\"ptag\">Live &middot; engineering org</span>\n        </div>\n        <p class=\"psub\">The team brain for a software engineering organization</p>\n        <p>Slack threads, Jira tickets, GitHub commits and PRs, Confluence pages, Google Docs, and Zoom transcripts ingest into immutable raw sources. An LLM-maintained wiki sits on top: <b>an entity page per team member and per repository</b>, expertise maps, an onboarding guide, curated Q&amp;A — with a deterministic lint loop keeping it honest.</p>\n        <ul>\n          <li><b>Five daily syncs</b> keep it current — Slack, GitHub, Jira, Confluence, Google Docs — plus a weekly 7-check lint.</li>\n          <li>Each person&rsquo;s page aggregates their <b>tasks, meetings, PRs, reviews, commits, and Slack activity</b> — auto-attributed and linked.</li>\n          <li>Each repo&rsquo;s page carries every <b>pull request, review, and commit</b>, compiled nightly straight from git history.</li>\n          <li>The team asks Yoda in <b>Slack</b>; it answers from the wiki with wikilink citations, per the schema&rsquo;s rules.</li>\n          <li>Runs self-maintained on a <b>single cloud instance</b> — syncs commit their own updates back to the repo.</li>\n        </ul>\n        <div class=\"translate\">\n          <div class=\"tlabel\">What that means for any company</div>\n          <p>Every &ldquo;who owns this?&rdquo;, &ldquo;why did we build it this way?&rdquo;, and &ldquo;who&rsquo;s the expert on X?&rdquo; gets answered <b>in seconds, with receipts</b> — instead of interrupting your most senior people. New hires read one living onboarding guide and ask the brain the rest.</p>\n        </div>\n      </div>\n\n      <div class=\"prod reveal\">\n        <div class=\"phead\">\n          <span class=\"pic\"><svg fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-truck\"/></svg></span>\n          <h3>Nova</h3>\n          <span class=\"ptag\">Live &middot; freight brokerage</span>\n        </div>\n        <p class=\"psub\">The operations brain for a national logistics company</p>\n        <p>A Microsoft Teams assistant backed by a Karpathy-pattern brain re-cast for freight — <b>systems, processes, commission rules, people, customers, carriers, and offices</b> as living entity pages — plus a live connection into the McLeod TMS, so answers about loads, margins, and carriers come from the system of record itself.</p>\n        <ul>\n          <li>Chats where the team already lives: <b>Microsoft Teams</b>, with enterprise single sign-on.</li>\n          <li><b>Live + synced hybrid</b> — the wiki holds the institutional context; MCP tools read the TMS live at answer time.</li>\n          <li>An explicit <b>authority rule: the TMS is ground truth</b>. When wiki and TMS disagree, the TMS wins and the conflict is surfaced.</li>\n          <li>Teams, TMS, and GitHub syncs run on schedule; the brain handles <b>commission, payroll, and margin data privately</b> by design.</li>\n          <li>Dispatchers and brokers get policy answers <b>cited to the actual policy page</b> — not folklore from the loudest desk.</li>\n        </ul>\n        <div class=\"translate\">\n          <div class=\"tlabel\">What that means for any company</div>\n          <p>Swap the TMS for <b>your</b> system of record — the CRM, the ERP, the PMS, the deal room — and Nova&rsquo;s shape is your company&rsquo;s: institutional memory in chat, wired to live operational truth, safe with your most sensitive numbers.</p>\n        </div>\n      </div>\n\n    </div>\n    <p class=\"prod-foot reveal\">Same three layers under both. <b>Your brain is the third</b> — reshaped to your industry, your systems, your rules.</p>\n  </div>\n</section>\n\n<!-- CITATION SHOWCASE -->\n<section class=\"showcase\" id=\"showcase\">\n  <div class=\"wrap\">\n    <div class=\"show-grid\">\n      <div class=\"show-copy reveal\">\n        <span class=\"eyebrow\"><span class=\"dot\">&#9679;</span> Trust by construction</span>\n        <h2>If it can&rsquo;t cite it, it won&rsquo;t claim it.</h2>\n        <p>Endurance Brain was built around a single hard rule: <strong>every fact must trace to a real source.</strong> The schema rejects any synthesized claim that isn&rsquo;t backed by a link to the underlying email, thread, ticket, or document.</p>\n        <ul class=\"show-list\">\n          <li><svg fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-check\"/></svg><span>Born from a real failure mode — an early system once invented a profile from a job title with zero evidence. <em>The citation rule exists so that can never happen silently again.</em></span></li>\n          <li><svg fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-check\"/></svg><span>When evidence is thin, the brain <em>says so</em> rather than filling the gap with confident fiction.</span></li>\n          <li><svg fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-check\"/></svg><span>When the answer must be current, it reads the <em>live system of record</em> and cites the record it read.</span></li>\n          <li><svg fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-check\"/></svg><span>Every answer is one click from the primary source — built for legal, financial, and regulated work.</span></li>\n        </ul>\n      </div>\n      <div class=\"term-stack\">\n        <div class=\"terminal reveal\">\n          <div class=\"term-bar\"><i></i><i></i><i></i><span>ask &middot; endurance-brain &middot; wiki</span></div>\n          <div class=\"term-body\">\n<span class=\"q\">&gt; Who owns the Riverside acquisition and what&rsquo;s the latest?</span><br><br>\n<span class=\"a\">The Riverside acquisition is led by <b>D. Marsh</b> (Acquisitions).</span><br>\n<span class=\"dim\">  &#8627; source: </span><span class=\"cite\">[[email/2026-05-tour-recap]]</span><br>\n<span class=\"a\">LOI signed 5/28; DD closes 6/20. Survey flagged an</span><br>\n<span class=\"a\">easement on the north parcel — open item.</span><br>\n<span class=\"dim\">  &#8627; source: </span><span class=\"cite\">[[deal-room/Riverside#DD]]</span> <span class=\"dim\">&middot;</span> <span class=\"cite\">[[meeting/2026-06-09-IC]]</span><br><br>\n<span class=\"ok\">&#10003; 3 claims &middot; 3 cited &middot; 0 unverified</span><br>\n<span class=\"dim\">  lint: no contradictions &middot; sources current</span>\n          </div>\n        </div>\n        <div class=\"terminal reveal\">\n          <div class=\"term-bar\"><i></i><i></i><i></i><span>ask &middot; endurance-brain &middot; live systems</span></div>\n          <div class=\"term-body\">\n<span class=\"q\">&gt; What&rsquo;s the status of order 88214 and who&rsquo;s the carrier?</span><br><br>\n<span class=\"amber\">&#9889; live read &middot; TMS &middot; 0.4s</span><br>\n<span class=\"a\">Order 88214 is <b>in transit</b>, picked up this morning;</span><br>\n<span class=\"a\">carrier is under an active contract, insurance current.</span><br>\n<span class=\"dim\">  &#8627; source: </span><span class=\"cite\">[tms/orders/88214 — live record]</span><br>\n<span class=\"dim\">  &#8627; context: </span><span class=\"cite\">[[wiki/carriers/… — history &amp; notes]]</span><br><br>\n<span class=\"ok\">&#10003; authority rule: TMS is ground truth</span>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- FIELD NOTES -->\n<section class=\"notes\" id=\"notes\">\n  <div class=\"wrap\">\n    <div class=\"sec-head center reveal\">\n      <span class=\"eyebrow\"><span class=\"dot\">&#9679;</span> Field notes</span>\n      <h2>What it actually does, day to day.</h2>\n      <p>One-line snapshots of how teams use a Brain once it&rsquo;s wired in — drawn from the patterns we see in production, translated to any industry.</p>\n    </div>\n    <div class=\"note-cols\">\n      <div class=\"note-col\">\n        <div class=\"note-group reveal\">\n          <h4>Onboarding &amp; continuity</h4>\n          <ul>\n            <li><b>New hire productive by Friday</b> — one living onboarding guide, the brain answers the rest.</li>\n            <li>The expert retired; <b>the expertise didn&rsquo;t</b>.</li>\n            <li>Account handoff without the handoff meeting — <b>the entity page already knows the history</b>.</li>\n            <li>PTO without the &ldquo;quick questions&rdquo; — the brain covers while you&rsquo;re out.</li>\n            <li>Six months of a departed PM&rsquo;s context, <b>still answerable</b>.</li>\n          </ul>\n        </div>\n        <div class=\"note-group reveal\">\n          <h4>Engineering</h4>\n          <ul>\n            <li>&ldquo;Why Postgres over Mongo?&rdquo; — <b>the two-year-old design thread</b>, found in seconds.</li>\n            <li>A repo page listing <b>every PR, review, and commit</b> — compiled nightly, linked to GitHub.</li>\n            <li>&ldquo;What shipped last month?&rdquo; answered across every repo without opening one.</li>\n            <li>The expertise map flags <b>who&rsquo;s actually touched the payments code</b> — before you ping the wrong three people.</li>\n            <li>Incident postmortems that cite the actual timeline, not memory of it.</li>\n          </ul>\n        </div>\n      </div>\n      <div class=\"note-col\">\n        <div class=\"note-group reveal\">\n          <h4>Operations &amp; logistics</h4>\n          <ul>\n            <li>Mid-call carrier question answered <b>from the live TMS</b> — no tab-switching, no hold.</li>\n            <li>Commission rule disputes settled by <b>the cited policy page</b>, not the loudest desk.</li>\n            <li>&ldquo;This customer&rsquo;s last five loads?&rdquo; — pulled from the system of record, in chat.</li>\n            <li>Lane and route playbooks that <b>update themselves</b> as the threads happen.</li>\n            <li>New broker learns the office&rsquo;s comp plan from the brain, <b>not by interrupting the manager</b>.</li>\n          </ul>\n        </div>\n        <div class=\"note-group reveal\">\n          <h4>Deals &amp; finance</h4>\n          <ul>\n            <li>&ldquo;Why did we pass on this deal last year?&rdquo; — <b>the pass-reason memo</b>, cited.</li>\n            <li>DD status answered from the data room <b>without opening the data room</b>.</li>\n            <li>IC prep where <b>every claim in the memo</b> is one click from its source.</li>\n            <li>&ldquo;What did we pay on comparable deals?&rdquo; — cited to the underwriting models.</li>\n            <li>Lender and partner history assembled per relationship, automatically.</li>\n          </ul>\n        </div>\n      </div>\n      <div class=\"note-col\">\n        <div class=\"note-group reveal\">\n          <h4>Sales &amp; client work</h4>\n          <ul>\n            <li>&ldquo;What did we promise this client in March?&rdquo; — <b>the thread, the doc, and the call transcript</b>.</li>\n            <li>Every account page joins CRM records with <b>what was actually said</b> in chat and email.</li>\n            <li>Proposal context assembled from every prior engagement, in minutes.</li>\n            <li>Renewal risk spotted from the threads, <b>before the QBR</b>.</li>\n          </ul>\n        </div>\n        <div class=\"note-group reveal\">\n          <h4>Leadership &amp; trust</h4>\n          <ul>\n            <li>When two sources disagreed, the brain <b>surfaced both</b> instead of guessing.</li>\n            <li>The weekly lint found the stale org chart <b>before it misled anyone</b>.</li>\n            <li>Zero unbacked claims — <b>enforced by schema, verified on schedule</b>.</li>\n            <li>&ldquo;Who decided this, and when?&rdquo; — provenance on demand.</li>\n            <li>An auditable memory your compliance team can actually read — <b>it&rsquo;s plain files, versioned</b>.</li>\n          </ul>\n        </div>\n      </div>\n    </div>\n    <p class=\"notes-foot reveal\">Every one of these is the same three layers — ingest, synthesize, answer — pointed at a different corner of the business.</p>\n  </div>\n</section>\n\n<!-- CAPABILITIES -->\n<section class=\"features\" id=\"features\">\n  <div class=\"wrap\">\n    <div class=\"sec-head reveal\">\n      <span class=\"eyebrow\"><span class=\"dot\">&#9679;</span> Capabilities</span>\n      <h2>Everything a knowledge base should have been all along.</h2>\n      <p>Not a search box bolted onto your data. A structured, self-governing system designed so the answers are trustworthy by construction — with a practical payoff attached to every piece.</p>\n    </div>\n    <div class=\"feat-grid\">\n      <div class=\"feat reveal\">\n        <div class=\"ic\"><svg fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-link\"/></svg></div>\n        <h3>Citations on every claim</h3>\n        <p>No statement reaches your team without a link to the exact email, message, or document it came from. Trust, then verify — in one click.</p>\n        <div class=\"fex\"><b>In practice:</b> disputes end at the source, not in a meeting.</div>\n      </div>\n      <div class=\"feat reveal\">\n        <div class=\"ic\"><svg fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-person\"/></svg></div>\n        <h3>Entity pages</h3>\n        <p>A living profile for every person, client, deal, carrier, property, vendor, repo, and project — auto-assembled from everything they&rsquo;ve touched across your stack.</p>\n        <div class=\"fex\"><b>In practice:</b> account handoffs and 1:1 prep in one page.</div>\n      </div>\n      <div class=\"feat reveal\">\n        <div class=\"ic\"><svg fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-layers\"/></svg></div>\n        <h3>Synthesis pages</h3>\n        <p>Expertise maps, onboarding guides, and curated Q&amp;A compiled by the LLM and kept current — the institutional knowledge you wish you&rsquo;d written down.</p>\n        <div class=\"fex\"><b>In practice:</b> the onboarding doc that never goes stale.</div>\n      </div>\n      <div class=\"feat reveal\">\n        <div class=\"ic\"><svg fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-refresh\"/></svg></div>\n        <h3>Self-maintaining</h3>\n        <p>Scheduled syncs ingest new activity around the clock and re-compile the wiki automatically — and commit their own updates back, versioned.</p>\n        <div class=\"fex\"><b>In practice:</b> zero librarians hired. Zero wiki gardening days.</div>\n      </div>\n      <div class=\"feat reveal\">\n        <div class=\"ic\"><svg fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-bolt\"/></svg></div>\n        <h3>Live system reads (MCP)</h3>\n        <p>When the answer must be current to the second, the Brain queries your system of record live — TMS, CRM, ERP — and cites the record it read.</p>\n        <div class=\"fex\"><b>In practice:</b> operational questions answered mid-call.</div>\n      </div>\n      <div class=\"feat reveal\">\n        <div class=\"ic\"><svg fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-shield\"/></svg></div>\n        <h3>Deterministic lint</h3>\n        <p>A rules engine scans on schedule for contradictions, stale data, and unbacked claims — flagging them before they ever mislead a decision.</p>\n        <div class=\"fex\"><b>In practice:</b> the stale org chart gets caught, not quoted.</div>\n      </div>\n      <div class=\"feat reveal\">\n        <div class=\"ic\"><svg fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-scale\"/></svg></div>\n        <h3>Authority &amp; conflict rules</h3>\n        <p>When sources disagree, a strict precedence decides what wins — the system of record beats the wiki, the wiki beats the rumor — and the discrepancy is surfaced, never silently resolved.</p>\n        <div class=\"fex\"><b>In practice:</b> &ldquo;the TMS is ground truth&rdquo; — by rule, not habit.</div>\n      </div>\n      <div class=\"feat reveal\">\n        <div class=\"ic\"><svg fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-chat\"/></svg></div>\n        <h3>Ask where you already work</h3>\n        <p>Slack, Microsoft Teams, the web app, or embedded in your own tools — with enterprise SSO. Answers land in the flow of work, not another tab.</p>\n        <div class=\"fex\"><b>In practice:</b> adoption without a rollout program.</div>\n      </div>\n      <div class=\"feat reveal\">\n        <div class=\"ic\"><svg fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-plug\"/></svg></div>\n        <h3>Extensible connectors</h3>\n        <p>Add a new source and the brain absorbs it. Connectors are modular — your DMS, ERP, deal room, or proprietary system plugs right in.</p>\n        <div class=\"fex\"><b>In practice:</b> the weird internal tool from 2011? Also connected.</div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- INDUSTRIES -->\n<section class=\"industries\" id=\"industries\">\n  <div class=\"wrap\">\n    <div class=\"sec-head center reveal\">\n      <span class=\"eyebrow\"><span class=\"dot\">&#9679;</span> Built for knowledge-heavy firms</span>\n      <h2>One brain. Every industry that runs on memory.</h2>\n      <p>Wherever decisions depend on context spread across people and tools, Endurance Brain becomes the system of record your team can finally trust.</p>\n    </div>\n    <div class=\"ind-grid\">\n      <div class=\"ind reveal\">\n        <div class=\"ihead\"><span class=\"iic\"><svg fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-scale\"/></svg></span><h3>Law Firms</h3></div>\n        <p>Turn every matter, brief, email, and deposition into instantly-searchable, cited institutional knowledge.</p>\n        <ul>\n          <li>Matter &amp; client history at a glance</li>\n          <li>Precedent &amp; clause retrieval with sources</li>\n          <li>Conflict checks across communications</li>\n          <li>Associate onboarding in days</li>\n        </ul>\n      </div>\n      <div class=\"ind reveal\">\n        <div class=\"ihead\"><span class=\"iic\"><svg fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-building\"/></svg></span><h3>Real Estate</h3></div>\n        <p>Every deal, property, lease, and lender conversation unified into one living deal-memory.</p>\n        <ul>\n          <li>Per-property &amp; per-deal entity pages</li>\n          <li>Underwriting context &amp; DD status</li>\n          <li>Broker, lender &amp; partner history</li>\n          <li>IC memos backed by cited sources</li>\n        </ul>\n      </div>\n      <div class=\"ind reveal\">\n        <div class=\"ihead\"><span class=\"iic\"><svg fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-truck\"/></svg></span><h3>Logistics &amp; Supply Chain</h3></div>\n        <p>Carriers, lanes, SOPs, and exceptions captured — with the TMS wired in live, the way Nova runs today.</p>\n        <ul>\n          <li>Carrier &amp; vendor performance memory</li>\n          <li>Live TMS reads at answer time</li>\n          <li>Incident &amp; exception history with root cause</li>\n          <li>SOPs that update themselves</li>\n        </ul>\n      </div>\n      <div class=\"ind reveal\">\n        <div class=\"ihead\"><span class=\"iic\"><svg fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-rocket\"/></svg></span><h3>Venture Capital</h3></div>\n        <p>Founders, deals, diligence, and portfolio context compiled into a fund-wide memory.</p>\n        <ul>\n          <li>Company &amp; founder dossiers, auto-built</li>\n          <li>Deal pipeline &amp; pass-reason history</li>\n          <li>Portfolio updates synthesized continuously</li>\n          <li>Warm-intro &amp; relationship graph</li>\n        </ul>\n      </div>\n      <div class=\"ind reveal\">\n        <div class=\"ihead\"><span class=\"iic\"><svg fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-chart\"/></svg></span><h3>Private Equity</h3></div>\n        <p>Diligence, portfolio operations, and LP context in one auditable, cited knowledge base.</p>\n        <ul>\n          <li>Target &amp; portfolio-company entity pages</li>\n          <li>Diligence findings with source trails</li>\n          <li>Value-creation plan tracking</li>\n          <li>LP &amp; deal-team institutional memory</li>\n        </ul>\n      </div>\n      <div class=\"ind reveal\">\n        <div class=\"ihead\"><span class=\"iic\"><svg fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-bank\"/></svg></span><h3>Financial Services</h3></div>\n        <p>Research, client relationships, and compliance context unified with full audit trails.</p>\n        <ul>\n          <li>Client &amp; account history, cited</li>\n          <li>Research &amp; thesis synthesis</li>\n          <li>Audit-ready, immutable records</li>\n          <li>Cross-desk knowledge sharing</li>\n        </ul>\n      </div>\n      <div class=\"ind reveal\">\n        <div class=\"ihead\"><span class=\"iic\"><svg fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-briefcase\"/></svg></span><h3>Consulting &amp; Pro Services</h3></div>\n        <p>Every engagement, deliverable, and SME becomes reusable, attributable firm IP.</p>\n        <ul>\n          <li>Engagement &amp; client knowledge bases</li>\n          <li>Expertise maps — find the right SME fast</li>\n          <li>Reusable methodology &amp; deliverables</li>\n          <li>Proposal context at your fingertips</li>\n        </ul>\n      </div>\n      <div class=\"ind reveal\">\n        <div class=\"ihead\"><span class=\"iic\"><svg fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-heart\"/></svg></span><h3>Healthcare &amp; Life Sciences</h3></div>\n        <p>Protocols, research, and operational knowledge kept current and fully traceable.</p>\n        <ul>\n          <li>Protocol &amp; SOP knowledge base</li>\n          <li>Research &amp; trial context synthesis</li>\n          <li>Traceable, compliance-friendly answers</li>\n          <li>Cross-team continuity of knowledge</li>\n        </ul>\n      </div>\n      <div class=\"ind reveal\">\n        <div class=\"ihead\"><span class=\"iic\"><svg fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-cpu\"/></svg></span><h3>Engineering &amp; Manufacturing</h3></div>\n        <p>Specs, decisions, incidents, and tribal know-how captured before the experts retire.</p>\n        <ul>\n          <li>System &amp; product entity pages</li>\n          <li>Design-decision &amp; rationale history</li>\n          <li>Incident &amp; RCA knowledge base</li>\n          <li>Onboard engineers against living docs</li>\n        </ul>\n      </div>\n      <div class=\"ind reveal\">\n        <div class=\"ihead\"><span class=\"iic\"><svg fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-handshake\"/></svg></span><h3>Investment Banking &amp; M&amp;A</h3></div>\n        <p>Live deal context, precedent transactions, and counterparty history across every workstream.</p>\n        <ul>\n          <li>Deal &amp; counterparty entity pages</li>\n          <li>Precedent transaction memory</li>\n          <li>Data-room &amp; diligence synthesis</li>\n          <li>Pitch &amp; CIM context, cited</li>\n        </ul>\n      </div>\n      <div class=\"ind reveal\">\n        <div class=\"ihead\"><span class=\"iic\"><svg fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-calculator\"/></svg></span><h3>Accounting &amp; Audit</h3></div>\n        <p>Engagements, workpapers, and client history turned into a traceable, audit-ready knowledge base.</p>\n        <ul>\n          <li>Client &amp; engagement entity pages</li>\n          <li>Workpaper &amp; treatment precedent</li>\n          <li>Full source trail for every figure</li>\n          <li>Staff onboarding against live guidance</li>\n        </ul>\n      </div>\n      <div class=\"ind reveal\">\n        <div class=\"ihead\"><span class=\"iic\"><svg fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-umbrella\"/></svg></span><h3>Insurance</h3></div>\n        <p>Policies, claims, underwriting notes, and broker relationships unified into one cited memory.</p>\n        <ul>\n          <li>Policyholder &amp; claim entity pages</li>\n          <li>Underwriting precedent &amp; rationale</li>\n          <li>Claims history with source trail</li>\n          <li>Broker &amp; carrier relationship memory</li>\n        </ul>\n      </div>\n      <div class=\"ind reveal\">\n        <div class=\"ihead\"><span class=\"iic\"><svg fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-gem\"/></svg></span><h3>Wealth Mgmt &amp; Family Offices</h3></div>\n        <p>Client relationships, holdings, and decisions captured into discreet, fully-cited institutional memory.</p>\n        <ul>\n          <li>Household &amp; entity relationship maps</li>\n          <li>Investment decision &amp; rationale history</li>\n          <li>Advisor continuity across staff changes</li>\n          <li>Discreet, private deployment</li>\n        </ul>\n      </div>\n      <div class=\"ind reveal\">\n        <div class=\"ihead\"><span class=\"iic\"><svg fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-ruler\"/></svg></span><h3>Architecture &amp; Construction</h3></div>\n        <p>Every project, RFI, submittal, and change order captured before it scatters across email and drives.</p>\n        <ul>\n          <li>Per-project &amp; per-site entity pages</li>\n          <li>RFI, submittal &amp; change-order history</li>\n          <li>Spec &amp; design-decision rationale</li>\n          <li>Subcontractor performance memory</li>\n        </ul>\n      </div>\n      <div class=\"ind reveal\">\n        <div class=\"ihead\"><span class=\"iic\"><svg fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-cloud\"/></svg></span><h3>Technology &amp; SaaS</h3></div>\n        <p>Product decisions, customer context, and engineering knowledge in one self-maintaining brain — the Yoda pattern.</p>\n        <ul>\n          <li>Customer &amp; account entity pages</li>\n          <li>Product &amp; roadmap decision history</li>\n          <li>Per-repo engineering knowledge</li>\n          <li>Support &amp; success context, unified</li>\n        </ul>\n      </div>\n      <div class=\"ind reveal\">\n        <div class=\"ihead\"><span class=\"iic\"><svg fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-landmark\"/></svg></span><h3>Government &amp; Public Sector</h3></div>\n        <p>Programs, contracts, and institutional knowledge preserved across administrations and turnover.</p>\n        <ul>\n          <li>Program &amp; contract entity pages</li>\n          <li>Policy &amp; decision provenance</li>\n          <li>Continuity across staff turnover</li>\n          <li>Auditable, traceable answers</li>\n        </ul>\n      </div>\n      <div class=\"ind reveal\">\n        <div class=\"ihead\"><span class=\"iic\"><svg fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-bolt\"/></svg></span><h3>Energy &amp; Utilities</h3></div>\n        <p>Assets, projects, regulatory filings, and field knowledge captured into a durable, cited record.</p>\n        <ul>\n          <li>Asset &amp; site entity pages</li>\n          <li>Project &amp; permitting history</li>\n          <li>Regulatory &amp; compliance trail</li>\n          <li>Field &amp; operational know-how retained</li>\n        </ul>\n      </div>\n      <div class=\"ind reveal\">\n        <div class=\"ihead\"><span class=\"iic\"><svg fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-megaphone\"/></svg></span><h3>Media &amp; Agencies</h3></div>\n        <p>Clients, campaigns, and creative decisions become reusable, attributable agency IP.</p>\n        <ul>\n          <li>Client &amp; campaign entity pages</li>\n          <li>Creative brief &amp; decision history</li>\n          <li>Reusable playbooks &amp; case studies</li>\n          <li>Pitch context at your fingertips</li>\n        </ul>\n      </div>\n    </div>\n    <p style=\"text-align:center;margin-top:36px;color:var(--muted);font-size:14.5px\" class=\"reveal\">Also: Pharma &amp; Biotech &middot; Asset Management &middot; Nonprofits &middot; Education &amp; Research &middot; Hospitality &middot; Telecom — <a href=\"#cta\" data-jump class=\"blue\" style=\"font-weight:700\">if your firm runs on knowledge, the Brain fits &rarr;</a></p>\n  </div>\n</section>\n\n<!-- VERSUS -->\n<section class=\"versus\" id=\"versus\">\n  <div class=\"wrap\">\n    <div class=\"sec-head center reveal\">\n      <span class=\"eyebrow\"><span class=\"dot\">&#9679;</span> Why it&rsquo;s different</span>\n      <h2>Not another RAG chatbot.</h2>\n      <p>Most &ldquo;AI knowledge&rdquo; tools embed your documents and hope the model retrieves the right chunk. Endurance Brain is a governed system of record — structured, cited, and self-correcting.</p>\n    </div>\n    <div class=\"cmp reveal\">\n      <div class=\"col them\">\n        <h3>Generic AI search / RAG</h3>\n        <ul>\n          <li><svg fill=\"none\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-x\"/></svg>Confidently hallucinates with no source</li>\n          <li><svg fill=\"none\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-x\"/></svg>Opaque vector blobs you can&rsquo;t read or audit</li>\n          <li><svg fill=\"none\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-x\"/></svg>Re-embeds everything; quietly drifts stale</li>\n          <li><svg fill=\"none\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-x\"/></svg>No notion of conflicting sources</li>\n          <li><svg fill=\"none\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-x\"/></svg>Can&rsquo;t touch your live systems of record</li>\n          <li><svg fill=\"none\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-x\"/></svg>Ships your data to someone else&rsquo;s cloud</li>\n        </ul>\n      </div>\n      <div class=\"col us\">\n        <h3>Endurance Brain</h3>\n        <ul>\n          <li><svg fill=\"none\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-check\"/></svg>Every claim cites a verifiable source — or isn&rsquo;t made</li>\n          <li><svg fill=\"none\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-check\"/></svg>Human-readable wiki you fully own and audit</li>\n          <li><svg fill=\"none\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-check\"/></svg>Self-maintaining syncs keep it permanently current</li>\n          <li><svg fill=\"none\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-check\"/></svg>Authority rules resolve &amp; surface conflicts</li>\n          <li><svg fill=\"none\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-check\"/></svg>Reads your TMS / CRM / ERP live, at answer time</li>\n          <li><svg fill=\"none\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-check\"/></svg>Runs private, on your own infrastructure</li>\n        </ul>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- SECURITY -->\n<section class=\"deploy\" id=\"security\">\n  <div class=\"wrap\">\n    <div class=\"sec-head reveal\">\n      <span class=\"eyebrow\"><span class=\"dot\">&#9679;</span> Security &amp; deployment</span>\n      <h2>Your knowledge. Your infrastructure. Your control.</h2>\n      <p>Endurance Brain runs entirely within your environment — the production brains handle commission, payroll, and client-margin data every day. Sensitive material never leaves your perimeter, and you own every byte of the wiki it produces.</p>\n    </div>\n    <div class=\"dep-grid\">\n      <div class=\"dep reveal\">\n        <div class=\"ic\"><svg fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-server\"/></svg></div>\n        <h3>Self-hosted</h3>\n        <p>Deploys to your cloud or on-prem — a production brain runs on a single cloud instance. Your call, your tenancy.</p>\n      </div>\n      <div class=\"dep reveal\">\n        <div class=\"ic\"><svg fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-lock\"/></svg></div>\n        <h3>Private by default</h3>\n        <p>Raw source material stays inside your perimeter. Nothing is shared outside the team.</p>\n      </div>\n      <div class=\"dep reveal\">\n        <div class=\"ic\"><svg fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-key\"/></svg></div>\n        <h3>Your credentials</h3>\n        <p>Connectors use your own API tokens with read-only scopes. Least-privilege from day one.</p>\n      </div>\n      <div class=\"dep reveal\">\n        <div class=\"ic\"><svg fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-git\"/></svg></div>\n        <h3>Versioned &amp; auditable</h3>\n        <p>The wiki is plain, version-controlled files. Every change is tracked, diffable, reversible.</p>\n      </div>\n    </div>\n\n    <div class=\"expert-grid\">\n      <div class=\"expert-copy reveal\">\n        <span class=\"eyebrow\"><span class=\"dot\">&#9679;</span> World-class team &middot; institutional-grade security</span>\n        <h2>Built by AI experts who&rsquo;ve secured institutional-grade systems.</h2>\n        <p>Endurance Brain is engineered by a team that has spent its career building secure, mission-critical software for institutional-quality firms — where a single leaked record or unverifiable answer isn&rsquo;t an inconvenience, it&rsquo;s a liability. Security isn&rsquo;t a feature we added. It&rsquo;s the discipline the whole system is built on.</p>\n        <div class=\"pillars\">\n          <div class=\"pillar\">\n            <span class=\"pic2\"><svg fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-award\"/></svg></span>\n            <div><h4>Institutional pedigree</h4><p>Deep experience delivering software to law firms, financial institutions, and other regulated, high-stakes environments — where the security bar is set by the most demanding clients in the world.</p></div>\n          </div>\n          <div class=\"pillar\">\n            <span class=\"pic2\"><svg fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-shield\"/></svg></span>\n            <div><h4>Security-first engineering</h4><p>Defense-in-depth, least-privilege access, and a deny-by-default posture are baked into the architecture from the first line of code — not bolted on after launch.</p></div>\n          </div>\n          <div class=\"pillar\">\n            <span class=\"pic2\"><svg fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-radar\"/></svg></span>\n            <div><h4>AI you can actually trust</h4><p>The same rigor that powers the citation engine governs the system itself — every action is logged, attributable, and auditable, so you always know what the Brain accessed and why.</p></div>\n          </div>\n        </div>\n      </div>\n      <div class=\"sec-panel reveal\">\n        <div class=\"sp-top\">\n          <span class=\"shield\"><svg fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-lock\"/></svg></span>\n          <div><h4>Enterprise security posture</h4><span>How your knowledge stays protected</span></div>\n        </div>\n        <ul class=\"sec-checks\">\n          <li><svg fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-check\"/></svg><span><b>Runs in your environment</b> — self-hosted on your cloud or on-prem; data never leaves your perimeter.</span></li>\n          <li><svg fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-check\"/></svg><span><b>Encrypted in transit &amp; at rest</b> — modern encryption everywhere your knowledge lives and moves.</span></li>\n          <li><svg fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-check\"/></svg><span><b>Least-privilege connectors</b> — every integration uses your own read-only, scoped credentials.</span></li>\n          <li><svg fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-check\"/></svg><span><b>Role-based access &amp; SSO</b> — the production Teams brain runs behind enterprise single sign-on today.</span></li>\n          <li><svg fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-check\"/></svg><span><b>Immutable audit trail</b> — an append-only record of every ingest, answer, and change.</span></li>\n          <li><svg fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-check\"/></svg><span><b>Single-tenant isolation</b> — your Brain is yours alone; never co-mingled with another firm&rsquo;s data.</span></li>\n          <li><svg fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-check\"/></svg><span><b>Compliance-ready architecture</b> — designed to support the controls regulated industries require.</span></li>\n        </ul>\n        <div class=\"sec-foot\">\n          <span class=\"nt\"><svg fill=\"none\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><use href=\"#i-eyeoff\"/></svg>Your data is never used to train external models</span>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- STATS BAND -->\n<div class=\"band\">\n  <div class=\"wrap\">\n    <div class=\"stat reveal\"><b>40+</b><span>connectable systems, named above</span></div>\n    <div class=\"stat reveal\"><b>100%</b><span>of claims carry a citation</span></div>\n    <div class=\"stat reveal\"><b>2</b><span>brains live in production</span></div>\n    <div class=\"stat reveal\"><b>24/7</b><span>autonomous syncing &amp; lint</span></div>\n  </div>\n</div>\n\n<!-- QUOTE -->\n<section class=\"quote\">\n  <div class=\"wrap reveal\">\n    <div class=\"qmark\">&ldquo;</div>\n    <blockquote>The team&rsquo;s knowledge used to live in people&rsquo;s heads and a thousand Slack threads. Now it lives in <span class=\"blue\">one brain that cites its work</span> — and it keeps itself current while we sleep.</blockquote>\n    <div class=\"qattr\">— Built and proven in production by the engineering team at Endurance AI Labs</div>\n  </div>\n</section>\n\n<!-- FAQ -->\n<section class=\"faq\" id=\"faq\">\n  <div class=\"wrap\">\n    <div class=\"sec-head center reveal\">\n      <span class=\"eyebrow\"><span class=\"dot\">&#9679;</span> FAQ</span>\n      <h2>Questions, answered.</h2>\n    </div>\n    <div class=\"faq-list reveal\">\n      <div class=\"qa\">\n        <button>Is this actually running anywhere, or is it a concept?<span class=\"pm\">+</span></button>\n        <div class=\"ans\"><p>It&rsquo;s deployed. <b>Yoda</b> runs daily for a software engineering organization — five scheduled syncs across Slack, Jira, GitHub, Confluence, Google Docs, and Zoom, answering in Slack with citations. <b>Nova</b> runs for a national freight brokerage in Microsoft Teams, combining a logistics knowledge base with live reads of the McLeod TMS. Your Brain would be the same architecture, reshaped to your industry.</p></div>\n      </div>\n      <div class=\"qa\">\n        <button>How is this different from a search tool or a wiki?<span class=\"pm\">+</span></button>\n        <div class=\"ans\"><p>A wiki goes stale the moment you stop editing it; a search tool just finds documents. Endurance Brain <b>writes and maintains the wiki for you</b> — continuously synthesizing your raw sources into structured, cited pages, and linting itself for contradictions and staleness. You get the readability of a wiki with the freshness of a live feed.</p></div>\n      </div>\n      <div class=\"qa\">\n        <button>How does it avoid making things up?<span class=\"pm\">+</span></button>\n        <div class=\"ans\"><p>The schema enforces a hard citation rule: no synthesized claim is allowed without a link to a real underlying source. When evidence is thin, the brain states that explicitly instead of guessing. A deterministic lint pass continuously flags any unbacked claim. Trust isn&rsquo;t a setting — it&rsquo;s built into how the system is constructed.</p></div>\n      </div>\n      <div class=\"qa\">\n        <button>Can it read our live systems, or only synced copies?<span class=\"pm\">+</span></button>\n        <div class=\"ans\"><p>Both — and that&rsquo;s the point. Historical context comes from the synced, immutable record; operational answers come from <b>live MCP connections</b> to your system of record at the moment you ask. In production today, that&rsquo;s a TMS: ask about an order and the Brain reads the live record, cites it, and treats it as ground truth over anything in the wiki. Your CRM, ERP, or PMS works the same way.</p></div>\n      </div>\n      <div class=\"qa\">\n        <button>Where does our data live?<span class=\"pm\">+</span></button>\n        <div class=\"ans\"><p>Entirely in your environment. Endurance Brain self-hosts on your cloud or on-prem infrastructure. Raw source material — emails, documents, messages — never leaves your perimeter, and connectors authenticate with your own read-only credentials. The production brains handle commission, payroll, and client-margin data under this posture every day.</p></div>\n      </div>\n      <div class=\"qa\">\n        <button>Which tools can it connect to?<span class=\"pm\">+</span></button>\n        <div class=\"ans\"><p>Out of the box: Outlook/Exchange, Gmail, Slack, Microsoft Teams, Zoom/Meet transcripts, Google Drive, SharePoint &amp; OneDrive, Box, Dropbox, Notion, Confluence, Guru, Jira, Linear, Asana, Monday, ClickUp, Trello, ServiceNow, Zendesk, Gong, Fireflies, Otter, Salesforce, HubSpot, Dynamics, NetSuite, SAP, Oracle, Airtable, QuickBooks, Xero, DocuSign, deal rooms (Datasite, Intralinks), industry DMS (iManage, NetDocuments), TMS platforms (McLeod), Procore, Yardi/RealPage/AppFolio, GitHub, GitLab, Bitbucket, Azure DevOps, SQL databases, Snowflake, BigQuery, and S3. The connector layer is modular — if a system has an API, it can be added; if it doesn&rsquo;t, we build the connector.</p></div>\n      </div>\n      <div class=\"qa\">\n        <button>How much upkeep does it require?<span class=\"pm\">+</span></button>\n        <div class=\"ans\"><p>Effectively none. Scheduled syncs ingest new activity and re-compile the wiki automatically around the clock — in production they even commit their own updates back to the versioned record. A human operator can steer high-level synthesis and review lint findings, but the brain stays current on its own.</p></div>\n      </div>\n      <div class=\"qa\">\n        <button>How long until it&rsquo;s useful?<span class=\"pm\">+</span></button>\n        <div class=\"ans\"><p>The first full ingest builds a usable brain from your existing history immediately — then it only compounds. New hires can start asking questions on day one instead of waiting months to absorb tribal knowledge.</p></div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- CTA -->\n<section class=\"cta\" id=\"cta\">\n  <div class=\"glow\"></div>\n  <div class=\"cta-in\">\n    <div class=\"wrap\">\n      <span class=\"eyebrow reveal\" style=\"color:var(--tl-accent2)\"><span class=\"dot\">&#9679;</span> Get started</span>\n      <h2 class=\"reveal\">Give your firm a memory<span class=\"blue\">that never forgets.</span></h2>\n      <p class=\"reveal\">Deploy Endurance Brain on your infrastructure and turn a decade of scattered context into one cited, self-maintaining source of truth — wired into every system you run.</p>\n      <div class=\"cta-row reveal\">\n        <a href=\"#\" data-demo class=\"btn btn-blue\">Book a demo &nbsp;&rarr;</a>\n        <a href=\"#how\" data-jump class=\"btn btn-ghost\">See how it works</a>\n      </div>\n      <p class=\"fine reveal\">Private deployment &middot; Your data stays yours &middot; Proven in production &middot; Built by Endurance AI Labs</p>\n    </div>\n  </div>\n</section>\n\n<!-- FOOTER -->\n<footer>\n  <div class=\"wrap\">\n    <div class=\"foot-grid\">\n      <div class=\"foot-brand\">\n        <a href=\"#top\" data-jump class=\"brand\" aria-label=\"Endurance AI Labs — Brain\">\n          <img src=\"/logo-endurance-white.svg\" alt=\"Endurance AI Labs\" class=\"wordmark\" style=\"height:22px\" />\n          <span class=\"bdiv\"></span>\n          <span class=\"bprod\">Brain</span>\n        </a>\n        <p>Autonomous institutional memory for knowledge-heavy firms. Every source, unified. Every claim, cited. Proven in production.</p>\n      </div>\n      <div class=\"foot-col\">\n        <h4>Product</h4>\n        <a href=\"#how\" data-jump>How it works</a>\n        <a href=\"#production\" data-jump>In production</a>\n        <a href=\"#features\" data-jump>Capabilities</a>\n        <a href=\"#security\" data-jump>Security</a>\n        <a href=\"/brain/reel\">&#9654; Watch the reel</a>\n        <a href=\"/brain/console\">Open the console</a>\n      </div>\n      <div class=\"foot-col\">\n        <h4>Industries</h4>\n        <a href=\"#industries\" data-jump>Law Firms</a>\n        <a href=\"#industries\" data-jump>Real Estate</a>\n        <a href=\"#industries\" data-jump>Logistics</a>\n        <a href=\"#industries\" data-jump>VC &amp; Private Equity</a>\n      </div>\n      <div class=\"foot-col\">\n        <h4>Company</h4>\n        <a href=\"#\" data-demo>Book a demo</a>\n        <a href=\"#\" data-demo>Contact</a>\n        <a href=\"#faq\" data-jump>FAQ</a>\n      </div>\n    </div>\n    <div class=\"foot-bot\">\n      <p>&copy; 2026 Endurance AI Labs. All rights reserved.</p>\n      <p class=\"coords\">68&deg;44&prime;21&Prime;S <span class=\"dot\">&middot;</span> 52&deg;19&prime;47&Prime;W — Endurance</p>\n    </div>\n  </div>\n</footer>\n\n<!-- SVG ICON SPRITE -->\n<svg width=\"0\" height=\"0\" style=\"position:absolute\" aria-hidden=\"true\">\n  <defs>\n    <g id=\"i-link\"><path d=\"M10 13a5 5 0 0 0 7 0l3-3a5 5 0 0 0-7-7l-1 1\"/><path d=\"M14 11a5 5 0 0 0-7 0l-3 3a5 5 0 0 0 7 7l1-1\"/></g>\n    <g id=\"i-person\"><circle cx=\"12\" cy=\"8\" r=\"4\"/><path d=\"M4 21a8 8 0 0 1 16 0\"/></g>\n    <g id=\"i-layers\"><path d=\"m12 2 9 5-9 5-9-5 9-5Z\"/><path d=\"m3 12 9 5 9-5\"/><path d=\"m3 17 9 5 9-5\"/></g>\n    <g id=\"i-refresh\"><path d=\"M21 12a9 9 0 1 1-3-6.7\"/><path d=\"M21 4v5h-5\"/></g>\n    <g id=\"i-shield\"><path d=\"M12 2 4 5v6c0 5 3.5 8.5 8 11 4.5-2.5 8-6 8-11V5l-8-3Z\"/><path d=\"m9 12 2 2 4-4\"/></g>\n    <g id=\"i-scale\"><path d=\"M12 3v18M5 21h14M7 7l-3 7h6l-3-7Zm10 0-3 7h6l-3-7ZM5 7h14\"/></g>\n    <g id=\"i-chat\"><path d=\"M21 15a2 2 0 0 1-2 2H8l-5 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2Z\"/></g>\n    <g id=\"i-clock\"><circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M12 7v5l3 2\"/></g>\n    <g id=\"i-plug\"><path d=\"M9 2v6M15 2v6M6 8h12v3a6 6 0 0 1-12 0Z\"/><path d=\"M12 17v5\"/></g>\n    <g id=\"i-check\"><path d=\"M20 6 9 17l-5-5\"/></g>\n    <g id=\"i-x\"><path d=\"M18 6 6 18M6 6l12 12\"/></g>\n    <g id=\"i-building\"><path d=\"M4 21V5a2 2 0 0 1 2-2h7a2 2 0 0 1 2 2v16\"/><path d=\"M15 9h3a2 2 0 0 1 2 2v10\"/><path d=\"M8 7h2M8 11h2M8 15h2\"/></g>\n    <g id=\"i-truck\"><path d=\"M1 6h13v9H1zM14 9h4l3 3v3h-7z\"/><circle cx=\"6\" cy=\"18\" r=\"2\"/><circle cx=\"18\" cy=\"18\" r=\"2\"/></g>\n    <g id=\"i-rocket\"><path d=\"M5 13c-1.5.5-3 2-3 6 4 0 5.5-1.5 6-3\"/><path d=\"M14 4c4 0 6 2 6 6 0 5-4 8-10 12C6 18 4 14 4 10c4-6 7-6 10-6Z\"/><circle cx=\"13\" cy=\"9\" r=\"1.5\"/></g>\n    <g id=\"i-chart\"><path d=\"M3 3v18h18\"/><path d=\"m7 14 3-4 3 3 4-6\"/></g>\n    <g id=\"i-bank\"><path d=\"M3 10 12 4l9 6M4 10h16M5 10v8M19 10v8M9 10v8M15 10v8M3 21h18\"/></g>\n    <g id=\"i-briefcase\"><rect x=\"3\" y=\"7\" width=\"18\" height=\"13\" rx=\"2\"/><path d=\"M8 7V5a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2M3 13h18\"/></g>\n    <g id=\"i-heart\"><path d=\"M19 5a5 5 0 0 0-7 0l0 0-0 0a5 5 0 0 0-7 7l7 7 7-7a5 5 0 0 0 0-7Z\"/></g>\n    <g id=\"i-cpu\"><rect x=\"6\" y=\"6\" width=\"12\" height=\"12\" rx=\"2\"/><path d=\"M9 1v3M15 1v3M9 20v3M15 20v3M1 9h3M1 15h3M20 9h3M20 15h3\"/></g>\n    <g id=\"i-server\"><rect x=\"3\" y=\"4\" width=\"18\" height=\"7\" rx=\"2\"/><rect x=\"3\" y=\"13\" width=\"18\" height=\"7\" rx=\"2\"/><path d=\"M7 7.5h.01M7 16.5h.01\"/></g>\n    <g id=\"i-lock\"><rect x=\"4\" y=\"11\" width=\"16\" height=\"10\" rx=\"2\"/><path d=\"M8 11V7a4 4 0 0 1 8 0v4\"/></g>\n    <g id=\"i-key\"><circle cx=\"8\" cy=\"8\" r=\"5\"/><path d=\"m11.5 11.5 8 8M16 16l2-2M19 19l2-2\"/></g>\n    <g id=\"i-git\"><circle cx=\"6\" cy=\"6\" r=\"2.5\"/><circle cx=\"6\" cy=\"18\" r=\"2.5\"/><circle cx=\"18\" cy=\"9\" r=\"2.5\"/><path d=\"M6 8.5v7M18 11.5c0 3-4 3.5-7 3.5\"/></g>\n    <g id=\"i-handshake\"><path d=\"m11 17 2 2a1.5 1.5 0 0 0 2-2\"/><path d=\"m13 17 2.5 2.5a1.5 1.5 0 0 0 2-2L13 13\"/><path d=\"M3 9 8 4l4 3 5-2 4 4\"/><path d=\"m3 9 4 4 3-2\"/><path d=\"m21 9-4 4\"/></g>\n    <g id=\"i-calculator\"><rect x=\"5\" y=\"2\" width=\"14\" height=\"20\" rx=\"2\"/><path d=\"M8 6h8M8 10h.01M12 10h.01M16 10h.01M8 14h.01M12 14h.01M16 14h4M8 18h.01M12 18h.01\"/></g>\n    <g id=\"i-umbrella\"><path d=\"M12 2a9 9 0 0 1 9 9H3a9 9 0 0 1 9-9Z\"/><path d=\"M12 11v8a2.5 2.5 0 0 1-5 0\"/></g>\n    <g id=\"i-gem\"><path d=\"M6 3h12l4 6-10 12L2 9Z\"/><path d=\"M2 9h20M9 3 6 9l6 12 6-12-3-6\"/></g>\n    <g id=\"i-ruler\"><path d=\"M3 17 17 3l4 4L7 21Z\"/><path d=\"M14 6l1.5 1.5M11 9l1.5 1.5M8 12l1.5 1.5M5 15l1.5 1.5\"/></g>\n    <g id=\"i-cloud\"><path d=\"M17.5 19a4.5 4.5 0 0 0 0-9 6 6 0 0 0-11.6-1.5A4 4 0 0 0 6 19Z\"/></g>\n    <g id=\"i-landmark\"><path d=\"M3 21h18M4 10h16M5 10 12 4l7 6M6 10v8M10 10v8M14 10v8M18 10v8\"/></g>\n    <g id=\"i-bolt\"><path d=\"M13 2 4 14h7l-1 8 9-12h-7Z\"/></g>\n    <g id=\"i-megaphone\"><path d=\"m3 11 15-6v14L3 13Z\"/><path d=\"M3 11v2a3 3 0 0 0 3 3h1M11 9v8\"/></g>\n    <g id=\"i-award\"><circle cx=\"12\" cy=\"9\" r=\"6\"/><path d=\"m8.5 14-1.5 7 5-3 5 3-1.5-7\"/></g>\n    <g id=\"i-eyeoff\"><path d=\"M9.9 5.1A9.5 9.5 0 0 1 12 5c6 0 10 7 10 7a17 17 0 0 1-3 3.6M6.3 6.3A17 17 0 0 0 2 12s4 7 10 7a9.5 9.5 0 0 0 4-.9\"/><path d=\"M9.5 9.5a3.5 3.5 0 0 0 5 5M3 3l18 18\"/></g>\n    <g id=\"i-radar\"><path d=\"M12 12 8 6\"/><path d=\"M21 12a9 9 0 1 1-5-8\"/><path d=\"M16 4a9 9 0 0 0-4 8\"/><circle cx=\"12\" cy=\"12\" r=\"2\"/></g>\n  </defs>\n</svg>\n\n<script>\n/* ============================================================\n   SCROLL ENGINE — the endurancelabs.ai \"dynamic jump\" feel:\n   inertial smooth-wheel scrolling (Lenis-style lerp) + eased\n   section jumps from nav / dots / anchors + scrollspy.\n   ============================================================ */\n(function(){\n  var reduced = matchMedia('(prefers-reduced-motion: reduce)').matches;\n  var fine = matchMedia('(pointer: fine)').matches;\n\n  var maxScroll = function(){ return Math.max(0, document.documentElement.scrollHeight - innerHeight); };\n\n  /* ---- inertial wheel smoothing ---- */\n  var target = scrollY, current = scrollY, wheelRaf = null, jumping = false;\n  function wheelTick(){\n    current += (target - current) * 0.105;\n    if (Math.abs(target - current) < 0.5){ current = target; wheelRaf = null; }\n    else wheelRaf = requestAnimationFrame(wheelTick);\n    scrollTo(0, Math.round(current));\n  }\n  if (!reduced && fine){\n    addEventListener('wheel', function(e){\n      if (e.ctrlKey || jumping) return;               // pinch-zoom / mid-jump: native\n      e.preventDefault();\n      var d = e.deltaY * (e.deltaMode === 1 ? 16 : e.deltaMode === 2 ? innerHeight : 1);\n      target = Math.max(0, Math.min(maxScroll(), target + d));\n      if (!wheelRaf) wheelRaf = requestAnimationFrame(wheelTick);\n    }, {passive:false});\n    // keep in sync when scrolled by scrollbar / keys / touch\n    addEventListener('scroll', function(){ if (!wheelRaf && !jumping){ current = target = scrollY; } }, {passive:true});\n  }\n\n  /* ---- eased section jumps ---- */\n  var NAVH = 64;\n  function jumpTo(el){\n    var from = scrollY;\n    var to = Math.max(0, Math.min(maxScroll(), el.getBoundingClientRect().top + scrollY - (el.id === 'top' ? 0 : NAVH)));\n    if (reduced){ scrollTo(0, to); return; }\n    var dist = Math.abs(to - from);\n    var dur = Math.min(1250, Math.max(550, dist * 0.45));\n    var t0 = null;\n    jumping = true;\n    if (wheelRaf){ cancelAnimationFrame(wheelRaf); wheelRaf = null; }\n    // if rAF is throttled (hidden tab), snap to the target instead of stalling\n    var fallback = setTimeout(function(){\n      if (jumping){ jumping = false; scrollTo(0, to); current = target = to; }\n    }, dur + 500);\n    function ease(t){ return t < .5 ? 4*t*t*t : 1 - Math.pow(-2*t+2, 3)/2; }\n    function step(ts){\n      if (!jumping) return;\n      if (t0 === null) t0 = ts;\n      var p = Math.min(1, (ts - t0) / dur);\n      scrollTo(0, Math.round(from + (to - from) * ease(p)));\n      if (p < 1) requestAnimationFrame(step);\n      else { clearTimeout(fallback); jumping = false; current = target = scrollY; }\n    }\n    requestAnimationFrame(step);\n  }\n  document.querySelectorAll('a[data-jump]').forEach(function(a){\n    a.addEventListener('click', function(e){\n      var id = a.getAttribute('href');\n      if (!id || id.charAt(0) !== '#') return;\n      var el = document.getElementById(id.slice(1));\n      if (!el) return;\n      e.preventDefault();\n      history.replaceState(null, '', id);\n      jumpTo(el);\n    });\n  });\n\n  /* ---- nav theme flip + progress bar ---- */\n  var nav = document.getElementById('nav'), rail = document.getElementById('rail'),\n      progress = document.getElementById('progress'), hero = document.getElementById('top');\n  function paint(){\n    var past = scrollY > hero.offsetHeight - 80;\n    nav.classList.toggle('paper', past);\n    // rail is over dark sections at hero + production + cta; approximate by nav state and section\n    progress.style.width = (maxScroll() ? (scrollY / maxScroll()) * 100 : 0) + '%';\n  }\n  addEventListener('scroll', paint, {passive:true});\n  addEventListener('resize', paint);\n  paint();\n\n  /* ---- scrollspy: nav links + dot rail ---- */\n  var spyIds = ['top','systems','how','production','notes','features','industries','security','faq','cta'];\n  var darkSecs = {top:1, production:1, cta:1};\n  var spyEls = spyIds.map(function(id){ return document.getElementById(id); }).filter(Boolean);\n  var navLinks = document.querySelectorAll('#navlinks a[data-jump]');\n  var dots = document.querySelectorAll('#rail a[data-sec]');\n  function spy(){\n    var mid = scrollY + innerHeight * 0.38, cur = spyEls[0];\n    for (var i = 0; i < spyEls.length; i++){\n      if (spyEls[i].offsetTop <= mid) cur = spyEls[i];\n    }\n    var id = cur.id;\n    navLinks.forEach(function(a){ a.classList.toggle('active', a.getAttribute('href') === '#' + id); });\n    dots.forEach(function(d){ d.classList.toggle('on', d.getAttribute('data-sec') === id); });\n    rail.classList.toggle('dark', !!darkSecs[id]);\n  }\n  addEventListener('scroll', spy, {passive:true});\n  spy();\n})();\n\n/* ---------- Reveal on scroll ---------- */\n(function(){\n  var io = new IntersectionObserver(function(es){\n    es.forEach(function(e){ if (e.isIntersecting){ e.target.classList.add('in'); io.unobserve(e.target); } });\n  }, {threshold:.12});\n  document.querySelectorAll('.reveal').forEach(function(el, i){\n    el.style.transitionDelay = (i % 3 * 60) + 'ms'; io.observe(el);\n  });\n  // fail-safe: anything already in view after load snaps visible\n  setTimeout(function(){\n    document.querySelectorAll('.reveal:not(.in)').forEach(function(el){\n      var r = el.getBoundingClientRect();\n      if (r.height > 0 && r.top < innerHeight * 0.7) el.classList.add('in');\n    });\n  }, 1400);\n})();\n\n/* ---------- FAQ accordion ---------- */\ndocument.querySelectorAll('.qa button').forEach(function(b){\n  b.addEventListener('click', function(){\n    var qa = b.parentElement, ans = qa.querySelector('.ans'), open = qa.classList.contains('open');\n    document.querySelectorAll('.qa').forEach(function(x){ x.classList.remove('open'); x.querySelector('.ans').style.maxHeight = null; });\n    if (!open){ qa.classList.add('open'); ans.style.maxHeight = ans.scrollHeight + 'px'; }\n  });\n});\n\n/* ---------- \"Book a demo\" mailto (assembled at runtime so it survives\n   Cloudflare email obfuscation and keeps addresses away from scrapers) ---------- */\n(function(){\n  var dom='endurancelabs'+'.'+'ai';\n  var cc=['ramzy','alex','nick'].map(function(u){return u+'@'+dom;}).join(',');\n  var subject=encodeURIComponent('Endurance Brain Demo Request');\n  var body=encodeURIComponent(\n    \"Hi Endurance team,\\n\\nI'd like to book a demo of Endurance Brain.\\n\\nName:\\nCompany:\\nRole:\\nUse case:\\n\\nThanks\"\n  );\n  var href='mailto:?cc='+cc+'&subject='+subject+'&body='+body;\n  document.querySelectorAll('a[data-demo]').forEach(function(a){\n    a.addEventListener('click',function(e){\n      e.preventDefault();\n      window.location.href=href;\n    });\n  });\n})();\n\n/* ---------- Hero network canvas (glowing node map, Margins blue) ---------- */\n(function(){\n  var c=document.getElementById('net'), x=c.getContext('2d');\n  var w,h,dpr,nodes=[],raf;\n  var BLUE='74,134,247';\n  function size(){\n    dpr=Math.min(devicePixelRatio||1,2);\n    w=c.clientWidth;h=c.clientHeight;\n    c.width=w*dpr;c.height=h*dpr;x.setTransform(dpr,0,0,dpr,0,0);\n    build();\n  }\n  function build(){\n    var density=Math.max(28,Math.min(74,Math.floor(w*h/17000)));\n    nodes=[];\n    for(var i=0;i<density;i++){\n      nodes.push({\n        x:Math.random()*w, y:Math.random()*h,\n        vx:(Math.random()-.5)*.26, vy:(Math.random()-.5)*.26,\n        r:Math.random()*2.6+1.4,\n        p:Math.random()*Math.PI*2\n      });\n    }\n  }\n  function frame(){\n    x.clearRect(0,0,w,h);\n    var R=185;\n    for(var i=0;i<nodes.length;i++){\n      var a=nodes[i];\n      for(var j=i+1;j<nodes.length;j++){\n        var b=nodes[j], dx=a.x-b.x, dy=a.y-b.y, d=Math.hypot(dx,dy);\n        if(d<R){\n          var o=(1-d/R)*.22;\n          x.strokeStyle='rgba('+BLUE+','+o+')';\n          x.lineWidth=1;\n          x.beginPath();x.moveTo(a.x,a.y);x.lineTo(b.x,b.y);x.stroke();\n        }\n      }\n    }\n    for(var k=0;k<nodes.length;k++){\n      var n=nodes[k];\n      n.x+=n.vx;n.y+=n.vy;n.p+=.022;\n      if(n.x<0||n.x>w)n.vx*=-1;\n      if(n.y<0||n.y>h)n.vy*=-1;\n      var tw=(Math.sin(n.p)*.4+.6);\n      x.beginPath();\n      x.fillStyle='rgba('+BLUE+','+(.09*tw)+')';\n      x.arc(n.x,n.y,n.r*3.4,0,Math.PI*2);x.fill();\n      x.beginPath();\n      x.fillStyle='rgba('+BLUE+','+(.65*tw+.3)+')';\n      x.shadowBlur=16;x.shadowColor='rgba('+BLUE+',.8)';\n      x.arc(n.x,n.y,n.r,0,Math.PI*2);x.fill();\n      x.shadowBlur=0;\n    }\n    raf=requestAnimationFrame(frame);\n  }\n  size();frame();\n  addEventListener('resize',function(){cancelAnimationFrame(raf);size();frame();});\n})();\n</script>\n</body>\n</html>\n";

